import { useEffect, useMemo, useState } from 'react'
import { BookOpen, CheckCircle2, ChevronDown, CirclePlay, Clock3, Code2, Database, Layers3, Play, Route, Search, Sparkles, Terminal, Trophy } from 'lucide-react'
import './LearningCenter.css'

const baseLessons = [
  { id:'py-1', track:'Python', level:'Basic', title:'Variables, data types & input', duration:'8 min', kind:'flow', summary:'Store information in names and choose the right type for each value.', explain:'A variable is a name that refers to a value. Common Python types include str (text), int (whole numbers), float (decimal numbers), and bool (True/False). Use type() to inspect a value.', code:'name = "Asha"\nage = 24\nscore = 82.5\nis_ready = True\nprint(type(age))  # <class \'int\'>', task:'Create variables for your name, years of experience, and whether you are job-ready. Print each value and its type.', video:'_uQrJ0TkZlc', videoTitle:'Python basics for beginners' },
  { id:'py-2', track:'Python', level:'Basic', title:'Conditions & loops', duration:'10 min', kind:'flow', summary:'Make decisions with if/elif/else and repeat work with loops.', explain:'Conditions select a path. A for loop iterates over a sequence; a while loop repeats while a condition stays true. Prefer a for loop when you know what collection to process.', code:'scores = [72, 88, 59]\nfor score in scores:\n    if score >= 60:\n        print("Pass", score)\n    else:\n        print("Practice more", score)', task:'Loop over five interview scores and print whether each score is at least 60.', video:'_uQrJ0TkZlc', videoTitle:'Python beginner walkthrough' },
  { id:'py-3', track:'Python', level:'Intermediate', title:'Functions, scope & reusable code', duration:'12 min', kind:'layers', summary:'Break problems into small functions with clear inputs and outputs.', explain:'A function packages logic behind a name. Parameters are inputs; return sends a result back to the caller. Keep functions focused and avoid relying on hidden global state.', code:'def average(scores):\n    if not scores:\n        return 0\n    return sum(scores) / len(scores)\n\nprint(average([70, 80, 90]))  # 80.0', task:'Write a function that accepts a list of numbers and returns the largest number. Handle an empty list.', video:'_uQrJ0TkZlc', videoTitle:'Python functions explained' },
  { id:'py-4', track:'Python', level:'Intermediate', title:'Lists, dictionaries & comprehensions', duration:'14 min', kind:'table', summary:'Choose the right collection to represent and transform data.', explain:'Lists preserve order and allow repeated values. Dictionaries map unique keys to values; assigning the same key again replaces its previous value. Comprehensions create a new collection from an iterable.', code:'candidate = {"name": "Asha", "score": 82}\ncandidates = [candidate, {"name": "Ravi", "score": 91}]\npassed = [c["name"] for c in candidates if c["score"] >= 80]\nprint(passed)  # [\'Asha\', \'Ravi\']', task:'Create a dictionary for a candidate and filter a list to names with a score above 75.', video:'_uQrJ0TkZlc', videoTitle:'Python collections overview' },
  { id:'py-5', track:'Python', level:'Advanced', title:'Generators & lazy evaluation', duration:'15 min', kind:'flow', summary:'Process large datasets one item at a time instead of loading everything into memory.', explain:'A generator function uses yield. Each next() resumes execution from the previous yield, preserving local state. This is useful for streaming files, API results, and data pipelines.', code:'def even_numbers(limit):\n    for number in range(limit):\n        if number % 2 == 0:\n            yield number\n\nfor item in even_numbers(6):\n    print(item)', task:'Build a generator that reads a list and yields only values above a threshold.', video:'_uQrJ0TkZlc', videoTitle:'Python iterators and generators' },
  { id:'py-6', track:'Python', level:'Advanced', title:'Decorators & robust error handling', duration:'16 min', kind:'layers', summary:'Add reusable behavior around functions and handle expected failures safely.', explain:'A decorator accepts a function and returns a wrapped function. try/except handles known exceptions; avoid catching every error silently. In APIs, validate inputs and return clear error responses.', code:'from functools import wraps\n\ndef trace(fn):\n    @wraps(fn)\n    def wrapper(*args, **kwargs):\n        print("Calling", fn.__name__)\n        return fn(*args, **kwargs)\n    return wrapper\n\n@trace\ndef greet(name):\n    return f"Hello, {name}"', task:'Explain what wrapper receives and why @wraps helps preserve function metadata.', video:'_uQrJ0TkZlc', videoTitle:'Python decorators explained' },
  { id:'sql-1', track:'SQL', level:'Basic', title:'Tables, SELECT & filtering', duration:'9 min', kind:'table', summary:'Read relational data and narrow results with WHERE.', explain:'A table stores rows and columns. SELECT chooses columns, FROM identifies the table, and WHERE filters rows. Use explicit column names rather than SELECT * in production queries.', code:'SELECT name, score\nFROM candidates\nWHERE score >= 70\nORDER BY score DESC;', task:'Write a query to show the top five candidates with scores of 70 or more.', video:'HXV3zeQKqGY', videoTitle:'SQL basics with examples' },
  { id:'sql-2', track:'SQL', level:'Intermediate', title:'JOINs, GROUP BY & aggregates', duration:'13 min', kind:'table', summary:'Combine related tables and summarize data accurately.', explain:'JOIN connects rows using a relationship. GROUP BY forms groups for aggregate functions such as COUNT, AVG, SUM, MIN, and MAX. Filter groups with HAVING; filter rows with WHERE.', code:'SELECT d.name, COUNT(c.id) AS candidate_count\nFROM departments d\nLEFT JOIN candidates c ON c.department_id = d.id\nGROUP BY d.name\nORDER BY candidate_count DESC;', task:'Explain why a LEFT JOIN can keep departments that have no candidates.', video:'HXV3zeQKqGY', videoTitle:'SQL joins and aggregation' },
  { id:'sql-3', track:'SQL', level:'Advanced', title:'Indexes, transactions & query plans', duration:'16 min', kind:'layers', summary:'Improve query performance without sacrificing data correctness.', explain:'Indexes can speed up lookups but add storage and write overhead. Transactions group changes; ACID describes atomicity, consistency, isolation, and durability. Use EXPLAIN/query plans to understand how a database executes a query.', code:'BEGIN;\nUPDATE inventory SET quantity = quantity - 1\nWHERE product_id = 42 AND quantity > 0;\n-- Check affected rows before COMMIT\nCOMMIT;', task:'Name two reasons an index may not help a query, and explain when a transaction should roll back.', video:'HXV3zeQKqGY', videoTitle:'SQL performance and transactions' },
  { id:'api-1', track:'REST APIs', level:'Basic', title:'HTTP methods & status codes', duration:'8 min', kind:'flow', summary:'Understand how clients and servers exchange resource representations.', explain:'GET reads, POST commonly creates, PUT replaces, PATCH partially updates, and DELETE removes a resource. Common status codes: 200 OK, 201 Created, 400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found, and 500 Internal Server Error.', code:'GET    /api/candidates/42  →  200 OK\nPOST   /api/candidates      →  201 Created\nPATCH  /api/candidates/42  →  200 OK\nDELETE /api/candidates/42  →  204 No Content', task:'Choose a method and expected status code for creating a candidate and fetching a missing candidate.', video:'GZvSYJDk-us', videoTitle:'REST API concepts' },
  { id:'api-2', track:'REST APIs', level:'Intermediate', title:'Validation, pagination & error responses', duration:'12 min', kind:'layers', summary:'Design predictable APIs that clients can use safely.', explain:'Validate untrusted input at the API boundary. Return consistent error shapes and useful status codes. Pagination with limit/offset or cursors prevents huge responses; enforce maximum page sizes.', code:'{\n  "error": {\n    "code": "VALIDATION_ERROR",\n    "message": "score must be between 0 and 100",\n    "field": "score"\n  }\n}', task:'Design a paginated endpoint response that includes results, page size, and a next-page indicator.', video:'GZvSYJDk-us', videoTitle:'API design patterns' },
  { id:'api-3', track:'REST APIs', level:'Advanced', title:'Authentication, authorization & rate limits', duration:'15 min', kind:'layers', summary:'Protect endpoints and keep services reliable under load.', explain:'Authentication establishes who a caller is; authorization checks what they can do. Keep secrets out of source code, use TLS, validate token issuer/audience/expiry, apply least privilege, and rate-limit abusive traffic. Never log access tokens.', code:'Request → TLS → Validate token → Check permission\n        → Apply rate limit → Run handler → Audit safe metadata', task:'Explain the difference between a 401 and a 403 response. List two controls for a public API.', video:'GZvSYJDk-us', videoTitle:'API security fundamentals' },

  // Python — continue in learning order
  { id:'py-7', track:'Python', level:'Basic', title:'Strings, slicing & formatting', duration:'10 min', kind:'table', summary:'Clean, inspect, slice and format text safely.', explain:'Strings are immutable sequences. Indexing selects one character and slicing selects a range. f-strings embed expressions in readable output. Use strip(), split(), and join() for common text cleanup.', code:'name = "  Asha Rao  ".strip()\nparts = name.split()\nprint(parts[0])\nprint(f"Candidate: {name}, score: {85:.1f}")', task:'Normalize a full name by trimming whitespace and print the first name and last name.', video:'_uQrJ0TkZlc', videoTitle:'Python strings and formatting' },
  { id:'py-8', track:'Python', level:'Basic', title:'Tuples, sets & choosing collections', duration:'9 min', kind:'table', summary:'Pick a collection based on ordering, uniqueness and mutability.', explain:'Tuples are ordered and immutable; sets store unique elements and support set operations; lists are ordered and mutable; dictionaries map unique keys to values. Choosing correctly improves clarity and performance.', code:'skills = ["Python", "SQL", "Python"]\nunique_skills = set(skills)\nrequired = {"Python", "SQL"}\nprint(unique_skills)\nprint(required.issubset(unique_skills))', task:'Remove duplicates from a list while preserving the original list unchanged.', video:'_uQrJ0TkZlc', videoTitle:'Python data structures' },
  { id:'py-9', track:'Python', level:'Basic', title:'Modules, packages & virtual environments', duration:'10 min', kind:'layers', summary:'Organize code and isolate project dependencies.', explain:'A module is a Python file; a package groups modules. Virtual environments isolate installed dependencies per project. Record dependencies so another developer can reproduce the setup.', code:'python -m venv .venv\n# Windows: .venv\\Scripts\\activate\n# macOS/Linux: source .venv/bin/activate\npython -m pip install requests\npython -m pip freeze > requirements.txt', task:'Explain why two Python projects may need different versions of the same package.', video:'_uQrJ0TkZlc', videoTitle:'Python modules and environments' },
  { id:'py-10', track:'Python', level:'Intermediate', title:'Files, JSON & context managers', duration:'12 min', kind:'flow', summary:'Read and write files while ensuring resources are closed.', explain:'The with statement uses a context manager to clean up resources even if an error occurs. The json module converts between Python values and JSON text. Specify encoding for predictable text handling.', code:'import json\n\nprofile = {"name": "Asha", "skills": ["Python", "SQL"]}\nwith open("profile.json", "w", encoding="utf-8") as file:\n    json.dump(profile, file, indent=2)\n\nwith open("profile.json", encoding="utf-8") as file:\n    loaded = json.load(file)', task:'Write a list of tasks to JSON and load it back. What exception might occur if the file is missing?', video:'_uQrJ0TkZlc', videoTitle:'Python files and JSON' },
  { id:'py-11', track:'Python', level:'Intermediate', title:'Exceptions, testing & debugging', duration:'13 min', kind:'layers', summary:'Find defects and make code behavior verifiable.', explain:'Raise specific exceptions for invalid states, catch only errors you can handle, and keep error messages useful. Unit tests check small units of behavior; boundary cases such as empty inputs often reveal bugs.', code:'def divide(a, b):\n    if b == 0:\n        raise ValueError("b must not be zero")\n    return a / b\n\ndef test_divide():\n    assert divide(10, 2) == 5\n', task:'Add tests for a normal division, a zero denominator, and a negative number.', video:'_uQrJ0TkZlc', videoTitle:'Python testing and exceptions' },
  { id:'py-12', track:'Python', level:'Intermediate', title:'OOP: classes, inheritance & composition', duration:'15 min', kind:'layers', summary:'Model related data and behavior with maintainable objects.', explain:'A class defines behavior and state; an instance is an object created from it. Inheritance models an “is-a” relationship, while composition models a “has-a” relationship. Prefer simple designs over unnecessary class hierarchies.', code:'class Course:\n    def __init__(self, title, lessons):\n        self.title = title\n        self.lessons = lessons\n\n    def remaining(self, completed):\n        return max(0, self.lessons - completed)\n\npython = Course("Python", 20)\nprint(python.remaining(7))', task:'Create a Student class with a name and scores, plus a method that calculates the average.', video:'_uQrJ0TkZlc', videoTitle:'Python object oriented programming' },
  { id:'py-13', track:'Python', level:'Advanced', title:'Iterators, closures & functional tools', duration:'14 min', kind:'flow', summary:'Understand iteration protocols and build reusable transformations.', explain:'An iterator implements __iter__() and __next__(). Closures retain references to variables from an enclosing scope. map(), filter(), and comprehensions transform data; choose the clearest option for your team.', code:'def make_multiplier(factor):\n    def multiply(value):\n        return value * factor\n    return multiply\n\ndouble = make_multiplier(2)\nprint(list(map(double, [1, 2, 3])))', task:'Write a closure that adds a configurable amount to any number.', video:'_uQrJ0TkZlc', videoTitle:'Python iterators and closures' },
  { id:'py-14', track:'Python', level:'Advanced', title:'Concurrency: threads, processes & async', duration:'18 min', kind:'flow', summary:'Choose a concurrency model based on the work being performed.', explain:'Threads are useful for many I/O-bound tasks; processes can use multiple CPU cores for CPU-bound work; async/await coordinates concurrent I/O without requiring a thread per task. Concurrency does not automatically make every workload faster.', code:'import asyncio\n\nasync def fetch_name(name):\n    await asyncio.sleep(0.1)\n    return f"Hello, {name}"\n\nasync def main():\n    results = await asyncio.gather(fetch_name("Asha"), fetch_name("Ravi"))\n    print(results)\n\nasyncio.run(main())', task:'Classify web requests, image resizing, and a large numerical calculation as I/O-bound or CPU-bound.', video:'_uQrJ0TkZlc', videoTitle:'Python concurrency explained' },
  { id:'py-15', track:'Python', level:'Advanced', title:'Performance, profiling & memory', duration:'17 min', kind:'layers', summary:'Measure bottlenecks before optimizing Python applications.', explain:'Start by measuring real workloads. Big-O notation describes how work scales; profiling finds hot paths. Generators can reduce peak memory, and caching can avoid repeated work—but caches need clear invalidation rules.', code:'from timeit import timeit\n\nvalues = list(range(10000))\nprint(timeit("sum(values)", globals=globals(), number=1000))\n\ndef squares(limit):\n    for value in range(limit):\n        yield value * value', task:'Compare the memory implications of building a list of one million values versus yielding them one at a time.', video:'_uQrJ0TkZlc', videoTitle:'Python profiling and optimization' },

  // SQL — complete the foundation, querying and administration path
  { id:'sql-4', track:'SQL', level:'Basic', title:'Primary keys, foreign keys & constraints', duration:'10 min', kind:'table', summary:'Protect data integrity with relational rules.', explain:'A primary key uniquely identifies each row. A foreign key enforces a relationship to another table. NOT NULL, UNIQUE, CHECK, and DEFAULT constraints prevent invalid or inconsistent data from entering the database.', code:'CREATE TABLE departments (\n  id INT PRIMARY KEY,\n  name VARCHAR(100) NOT NULL UNIQUE\n);\nCREATE TABLE employees (\n  id INT PRIMARY KEY,\n  department_id INT,\n  FOREIGN KEY (department_id) REFERENCES departments(id)\n);', task:'Design a courses table with a unique course code and a non-negative lesson count.', video:'HXV3zeQKqGY', videoTitle:'SQL tables and constraints' },
  { id:'sql-5', track:'SQL', level:'Basic', title:'NULL values, CASE & date functions', duration:'11 min', kind:'table', summary:'Handle missing values and create conditional output.', explain:'NULL represents an unknown or missing value; compare it with IS NULL rather than = NULL. COALESCE provides a fallback value. CASE expresses conditional logic in a query. Date functions vary by database engine.', code:'SELECT name,\n  CASE WHEN score >= 80 THEN \'Strong\'\n       WHEN score >= 60 THEN \'Pass\'\n       ELSE \'Review\' END AS result\nFROM candidates\nWHERE email IS NOT NULL;', task:'Write a CASE expression that labels scores as Excellent, Good, or Needs practice.', video:'HXV3zeQKqGY', videoTitle:'SQL NULL and CASE' },
  { id:'sql-6', track:'SQL', level:'Intermediate', title:'Subqueries, CTEs & window functions', duration:'15 min', kind:'layers', summary:'Break complex queries into readable stages and rank rows.', explain:'A subquery nests one query inside another. A common table expression (CTE) names a query result for reuse in the statement. Window functions calculate across related rows without collapsing them like GROUP BY does.', code:'WITH ranked AS (\n  SELECT name, department_id, score,\n    ROW_NUMBER() OVER (PARTITION BY department_id ORDER BY score DESC) AS rn\n  FROM candidates\n)\nSELECT name, department_id, score\nFROM ranked WHERE rn = 1;', task:'Return the second-highest score in each department using a window function.', video:'HXV3zeQKqGY', videoTitle:'SQL CTEs and window functions' },
  { id:'sql-7', track:'SQL', level:'Intermediate', title:'INSERT, UPDATE, DELETE & safe changes', duration:'10 min', kind:'flow', summary:'Modify rows carefully and verify the scope of every change.', explain:'INSERT creates rows, UPDATE changes matching rows, and DELETE removes matching rows. Always verify the WHERE clause and affected-row count. In production, use transactions and backups for risky changes.', code:'BEGIN TRANSACTION;\nUPDATE candidates\nSET score = 85\nWHERE id = 42;\n-- Verify affected rows and resulting data\nCOMMIT;', task:'Describe the risk of running UPDATE without WHERE and how you would reduce that risk.', video:'HXV3zeQKqGY', videoTitle:'SQL data modification safely' },
  { id:'sql-8', track:'SQL', level:'Intermediate', title:'Normalization & relational design', duration:'14 min', kind:'table', summary:'Reduce duplication and model relationships clearly.', explain:'Normalization separates distinct entities into related tables to reduce update anomalies. One-to-many relationships use foreign keys; many-to-many relationships typically use a junction table. Denormalization can be useful for measured performance needs.', code:'CREATE TABLE course_enrolments (\n  student_id INT NOT NULL,\n  course_id INT NOT NULL,\n  enrolled_at DATE NOT NULL,\n  PRIMARY KEY (student_id, course_id)\n);', task:'Model students enrolling in multiple courses. Explain why a junction table is needed.', video:'HXV3zeQKqGY', videoTitle:'Database normalization' },
  { id:'sql-9', track:'SQL', level:'Advanced', title:'Isolation levels & transaction anomalies', duration:'16 min', kind:'layers', summary:'Reason about concurrent updates and consistent reads.', explain:'Concurrent transactions can produce anomalies such as dirty reads, non-repeatable reads, and phantom rows. Isolation levels trade concurrency against consistency; exact behavior depends on the database engine. Keep transactions short and handle conflicts deliberately.', code:'BEGIN TRANSACTION;\nSELECT balance FROM accounts WHERE id = 7;\nUPDATE accounts SET balance = balance - 100 WHERE id = 7;\n-- Validate business rules before commit\nCOMMIT;', task:'Explain how two simultaneous withdrawals could overdraw an account and name a strategy to prevent it.', video:'HXV3zeQKqGY', videoTitle:'SQL transactions and isolation' },
  { id:'sql-10', track:'SQL', level:'Advanced', title:'Execution plans & index strategy', duration:'16 min', kind:'layers', summary:'Use query plans and workload evidence to tune slow queries.', explain:'An execution plan reveals scans, seeks, joins, estimates and costly operators. Index columns used in selective filters and joins, but account for write overhead and storage. Function-wrapped columns, implicit conversions, and low-selectivity predicates can limit index use.', code:'-- SQL Server example\nSET STATISTICS IO ON;\nSET STATISTICS TIME ON;\nSELECT id, name FROM candidates WHERE email = @email;\n-- Inspect the actual execution plan and logical reads', task:'A query scans a large table to find one email address. What evidence would you inspect before adding an index?', video:'HXV3zeQKqGY', videoTitle:'SQL query performance tuning' },
  { id:'sql-11', track:'SQL', level:'Advanced', title:'Views, stored procedures & parameters', duration:'14 min', kind:'table', summary:'Package reusable database logic and keep queries parameterized.', explain:'Views provide reusable query abstractions; stored procedures package database operations and can manage permissions. Parameterized queries separate values from SQL text and help prevent injection. Avoid building SQL by concatenating user input.', code:'-- Parameterized query concept\nSELECT id, name\nFROM candidates\nWHERE department_id = @department_id;', task:'Explain why parameterized SQL is safer than concatenating a search term into a query string.', video:'HXV3zeQKqGY', videoTitle:'SQL views and stored procedures' },
  { id:'sql-12', track:'SQL', level:'Advanced', title:'SQL security, backups & recovery', duration:'15 min', kind:'layers', summary:'Protect database access and plan for failures.', explain:'Grant least privilege, separate application and admin identities, rotate credentials, and audit sensitive access. Backups are useful only when restore procedures are tested. Define recovery point and recovery time objectives for critical systems.', code:'-- Principle: grant only the permissions needed\nGRANT SELECT ON dbo.course_catalog TO learning_reader;\n-- Backups and restore syntax vary by database platform.', task:'Explain the difference between recovery point objective (RPO) and recovery time objective (RTO).', video:'HXV3zeQKqGY', videoTitle:'Database security and recovery' },

  // REST APIs — from HTTP basics to production service design
  { id:'api-4', track:'REST APIs', level:'Basic', title:'Resources, URLs & JSON payloads', duration:'9 min', kind:'flow', summary:'Represent application data with consistent resource endpoints.', explain:'A REST-style API exposes resources using URLs and HTTP semantics. JSON is a common representation for request and response bodies. Use nouns for resource paths and keep response structures predictable.', code:'GET /api/courses/12\n\n{\n  "id": 12,\n  "title": "Python Foundations",\n  "published": true\n}', task:'Design endpoints to list courses, retrieve one course, and list lessons for that course.', video:'GZvSYJDk-us', videoTitle:'REST resources and JSON' },
  { id:'api-5', track:'REST APIs', level:'Basic', title:'Test APIs with curl or Postman', duration:'10 min', kind:'flow', summary:'Send requests and inspect headers, bodies and status codes.', explain:'An API client lets you test methods, query parameters, headers, authentication and JSON bodies. Test success and failure paths, including missing fields, invalid types and unauthorized requests. Never paste real secrets into shared screenshots.', code:'curl -i https://example.com/api/courses\n\ncurl -X POST https://example.com/api/courses \\\n  -H "Content-Type: application/json" \\\n  -d \'{"title":"Python Foundations"}\'', task:'Create a test checklist for a POST endpoint: success, missing title, invalid JSON, and unauthenticated request.', video:'GZvSYJDk-us', videoTitle:'Testing REST APIs' },
  { id:'api-6', track:'REST APIs', level:'Intermediate', title:'Build CRUD endpoints with Django REST Framework', duration:'16 min', kind:'layers', summary:'Connect serializers, views, URLs and models in a Django API.', explain:'In Django REST Framework, serializers validate and transform data; views or viewsets implement behavior; routers map viewsets to URLs. Keep business rules in an appropriate service or model layer and enforce permissions on every protected operation.', code:'from rest_framework import serializers, viewsets\nfrom .models import Course\n\nclass CourseSerializer(serializers.ModelSerializer):\n    class Meta:\n        model = Course\n        fields = ["id", "title", "published"]\n\nclass CourseViewSet(viewsets.ModelViewSet):\n    queryset = Course.objects.all()\n    serializer_class = CourseSerializer', task:'Trace a POST request from URL routing to validation and database persistence.', video:'GZvSYJDk-us', videoTitle:'Django REST Framework tutorial' },
  { id:'api-7', track:'REST APIs', level:'Intermediate', title:'ORM efficiency, filtering & pagination', duration:'14 min', kind:'layers', summary:'Avoid slow database access and keep list endpoints scalable.', explain:'N+1 queries happen when related records are fetched individually in a loop. Django select_related can join single-valued relationships; prefetch_related loads collections efficiently. Add allowlisted filters, stable ordering and bounded pagination.', code:'courses = Course.objects.select_related("category").prefetch_related("lessons")\n\n# API design: cap page_size and allow only approved ordering fields', task:'A course list triggers one query per course to load its category. Which ORM optimization would you consider?', video:'GZvSYJDk-us', videoTitle:'API pagination and database optimization' },
  { id:'api-8', track:'REST APIs', level:'Intermediate', title:'Automated API tests & documentation', duration:'13 min', kind:'table', summary:'Make endpoint behavior repeatable and understandable for consumers.', explain:'Automated tests cover status codes, response schemas, permissions, validation and edge cases. OpenAPI documents endpoints, parameters and response formats. Keep documentation aligned with tested behavior and avoid exposing private sample data.', code:'def test_course_not_found(client):\n    response = client.get("/api/courses/999999")\n    assert response.status_code == 404', task:'Write test cases for a protected endpoint: anonymous, permitted user, forbidden user, and malformed input.', video:'GZvSYJDk-us', videoTitle:'API testing and OpenAPI' },
  { id:'api-9', track:'REST APIs', level:'Advanced', title:'Idempotency, retries & timeouts', duration:'15 min', kind:'flow', summary:'Make network operations resilient to delays and duplicate requests.', explain:'Networks fail in partial ways. Set sensible timeouts, retry only appropriate failures with bounded exponential backoff and jitter, and avoid retry storms. Idempotent operations can be repeated safely; payment or create workflows may need idempotency keys.', code:'delay = min(base_delay * (2 ** attempt), max_delay)\n# Add random jitter before retrying.\n# Stop after a bounded number of attempts.', task:'A client times out after the server creates an order. Explain how an idempotency key prevents duplicate orders on retry.', video:'GZvSYJDk-us', videoTitle:'API retries and idempotency' },
  { id:'api-10', track:'REST APIs', level:'Advanced', title:'Caching, ETags & conditional requests', duration:'13 min', kind:'layers', summary:'Reduce repeated work while keeping clients aware of fresh data.', explain:'Cache-Control controls caching behavior. ETags identify a representation version; clients can send If-None-Match and receive 304 Not Modified when content has not changed. Do not cache private responses in shared caches without careful policy.', code:'HTTP/1.1 200 OK\nETag: "course-v7"\nCache-Control: private, max-age=60\n\n# Client later sends If-None-Match: "course-v7"', task:'Choose a caching strategy for a public course catalog and a private user profile.', video:'GZvSYJDk-us', videoTitle:'HTTP caching and ETags' },
  { id:'api-11', track:'REST APIs', level:'Advanced', title:'Background jobs, queues & webhooks', duration:'16 min', kind:'flow', summary:'Move slow or retryable work out of the request-response cycle.', explain:'A queue lets an API acknowledge work while a worker processes it asynchronously. Design jobs to be idempotent, observable and retry-safe; use dead-letter handling for repeated failures. Webhooks notify other systems and should be authenticated and verified.', code:'API request → validate → enqueue job → return 202 Accepted\nWorker → process → retry transient errors → record outcome', task:'Choose a background job for a learning platform and explain how you would handle duplicate delivery.', video:'GZvSYJDk-us', videoTitle:'Background jobs and webhooks' },
  { id:'api-12', track:'REST APIs', level:'Advanced', title:'Observability, versioning & deployment', duration:'17 min', kind:'layers', summary:'Operate APIs in production with useful signals and safe changes.', explain:'Structured logs, metrics and traces help explain failures and latency. Track request rate, errors and duration without logging secrets or personal data unnecessarily. Version APIs thoughtfully, use health checks, and deploy with rollback plans and backward-compatible database changes.', code:'Request → trace ID → structured logs + metrics\nDeploy → health check → monitor error rate/latency\nIf unhealthy → rollback or disable the change', task:'Define three API health indicators and explain what you would investigate if p95 latency suddenly rises.', video:'GZvSYJDk-us', videoTitle:'Production API monitoring and deployment' },

  // Additional language and infrastructure tracks
  { id:'java-1', track:'Java', level:'Basic', title:'Java syntax, variables & control flow', duration:'12 min', kind:'flow', summary:'Learn Java types, variables, conditions and loops.', explain:'Java is statically typed and runs on the JVM. Declare a type for each variable, use if/else for branching and for/while loops for repetition. The main method is a common entry point for standalone Java applications.', code:'public class Main {\n  public static void main(String[] args) {\n    String name = "StudyNest";\n    int lessons = 12;\n    if (lessons > 0) {\n      System.out.println(name + ": " + lessons);\n    }\n  }\n}', task:'Change the example to store a learner name and print whether they have completed at least five lessons.', video:'eIrMbAQSU34', videoTitle:'Java beginner tutorial' },
  { id:'java-2', track:'Java', level:'Intermediate', title:'Classes, objects & collections', duration:'15 min', kind:'layers', summary:'Model application concepts and work with lists of objects.', explain:'Classes define fields and methods; objects are instances of classes. Encapsulation protects internal state. Collections such as ArrayList store ordered groups of values, while generics make their element types explicit.', code:'import java.util.ArrayList;\n\nclass Course {\n  String title;\n  Course(String title) { this.title = title; }\n}\n\nvar courses = new ArrayList<Course>();\ncourses.add(new Course("Java"));\nSystem.out.println(courses.get(0).title);', task:'Add a method to Course that returns a formatted course description.', video:'eIrMbAQSU34', videoTitle:'Java classes and collections' },
  { id:'javascript-1', track:'JavaScript', level:'Basic', title:'Variables, functions & arrays', duration:'10 min', kind:'flow', summary:'Build a foundation in modern JavaScript syntax.', explain:'Use const by default and let when reassignment is needed. Functions package reusable behavior; arrays store ordered values. JavaScript is dynamically typed, so validate external data at system boundaries.', code:'const courses = ["HTML", "CSS", "JavaScript"];\nconst greet = (name) => `Welcome, ${name}!`;\nconsole.log(greet("Asha"));\nconsole.log(courses.length);', task:'Write a function that accepts an array of course names and returns the number of courses.', video:'W6NZfCO5SIk', videoTitle:'JavaScript fundamentals' },
  { id:'javascript-2', track:'JavaScript', level:'Intermediate', title:'Promises, async/await & fetch', duration:'14 min', kind:'layers', summary:'Handle asynchronous work and HTTP responses.', explain:'Promises represent future completion or failure. async/await makes promise-based code easier to read. fetch resolves for HTTP error statuses too, so check response.ok and handle network failures with try/catch.', code:'async function loadCourses() {\n  try {\n    const response = await fetch("/api/courses");\n    if (!response.ok) throw new Error("Request failed");\n    return await response.json();\n  } catch (error) {\n    console.error(error);\n    return [];\n  }\n}', task:'Explain why fetch does not automatically throw for a 404 response.', video:'W6NZfCO5SIk', videoTitle:'JavaScript async await' },
  { id:'c-1', track:'C Programming', level:'Basic', title:'C variables, types & input/output', duration:'11 min', kind:'flow', summary:'Understand compiled C programs and basic data types.', explain:'C is a compiled language with explicit types. printf prints formatted output and scanf can read input when used carefully. Every standalone program begins execution at main; compile with warnings enabled to catch mistakes early.', code:'#include <stdio.h>\n\nint main(void) {\n    int lessons = 5;\n    printf("Lessons: %d\\n", lessons);\n    return 0;\n}', task:'Add a float variable for course progress and print it with two decimal places.', video:'KJgsSFOSQv0', videoTitle:'C programming for beginners' },
  { id:'c-2', track:'C Programming', level:'Intermediate', title:'Pointers, arrays & memory basics', duration:'15 min', kind:'layers', summary:'Learn how addresses and pointers relate to array data.', explain:'A pointer stores a memory address. The address-of operator & obtains an address and * dereferences a pointer. Only dereference valid pointers; initialize pointers and respect object lifetimes to avoid undefined behavior.', code:'#include <stdio.h>\n\nint main(void) {\n    int score = 90;\n    int *score_ptr = &score;\n    printf("%d\\n", *score_ptr);\n    return 0;\n}', task:'Explain the difference between score_ptr and *score_ptr in the example.', video:'KJgsSFOSQv0', videoTitle:'C pointers explained' },
  { id:'htmlcss-1', track:'HTML & CSS', level:'Basic', title:'Semantic HTML & accessible page structure', duration:'9 min', kind:'table', summary:'Structure web pages with meaningful, accessible elements.', explain:'HTML describes document structure. Use semantic elements such as header, nav, main, section and footer to communicate meaning. Associate form labels with controls and provide useful alternative text for informative images.', code:'<main>\n  <h1>StudyNest</h1>\n  <section aria-labelledby="courses-title">\n    <h2 id="courses-title">Courses</h2>\n    <p>Choose a learning path.</p>\n  </section>\n</main>', task:'Create a semantic course card with a heading, short description and link.', video:'qz0aGYrrlhU', videoTitle:'HTML beginner course' },
  { id:'htmlcss-2', track:'HTML & CSS', level:'Intermediate', title:'CSS box model, flexbox & responsive layouts', duration:'13 min', kind:'layers', summary:'Build layouts that adapt to mobile and desktop screens.', explain:'The box model includes content, padding, border and margin. Flexbox aligns items along one dimension; Grid handles two-dimensional layouts. Media queries adapt layout to viewport size, and box-sizing:border-box makes sizing more predictable.', code:'* { box-sizing: border-box; }\n.course-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n  gap: 1rem;\n}\n.card { padding: 1rem; border-radius: 12px; }', task:'Make a three-column course grid that becomes one column on narrow screens.', video:'1PnVor36_40', videoTitle:'CSS flexbox and responsive design' },
  { id:'devops-1', track:'DevOps', level:'Basic', title:'DevOps lifecycle, Git & CI/CD', duration:'12 min', kind:'flow', summary:'Connect source control, automated checks and reliable releases.', explain:'DevOps combines collaboration and automation across development and operations. A CI pipeline builds and tests changes; CD automates delivery or deployment. Keep deployments repeatable, secrets protected and rollback procedures documented.', code:'Code commit → CI checks → Build artifact → Deploy to staging\n→ Smoke tests → Production rollout → Monitor → Roll back if needed', task:'Describe a simple pipeline for a React app and name two checks that should run before deployment.', video:'0yWAtQ6wYNM', videoTitle:'DevOps and CI/CD overview' },
  { id:'devops-2', track:'DevOps', level:'Intermediate', title:'Infrastructure as code, monitoring & releases', duration:'16 min', kind:'layers', summary:'Manage infrastructure consistently and observe application health.', explain:'Infrastructure as code describes resources declaratively and supports repeatable reviews. Monitoring combines metrics, logs and traces. Use environment-specific configuration, least-privilege access, health checks and staged or rolling deployments to reduce risk.', code:'Plan infrastructure change → Review diff → Apply in controlled environment\nDeploy app → Check health and error rate → Promote or roll back', task:'Choose three metrics for a web API and explain what action a sustained error-rate increase should trigger.', video:'0yWAtQ6wYNM', videoTitle:'Infrastructure as code and monitoring' },
  { id:'cloud-1', track:'Cloud Fundamentals', level:'Basic', title:'Cloud service models & regions', duration:'10 min', kind:'table', summary:'Understand IaaS, PaaS, SaaS and cloud regions.', explain:'IaaS provides configurable infrastructure, PaaS manages more of the runtime and platform, and SaaS delivers a finished application. Regions contain geographic infrastructure; availability zones help isolate failures. Select services based on reliability, cost, compliance and operational needs.', code:'Choose a service by asking:\n1. What does the team need to manage?\n2. Which regions and availability targets apply?\n3. What are the security and cost requirements?', task:'Compare a virtual machine with a managed application platform for a small web API.', video:'M988_fsOSWo', videoTitle:'Cloud computing fundamentals' },
  { id:'cloud-2', track:'Cloud Fundamentals', level:'Intermediate', title:'Identity, networking & cloud security', duration:'15 min', kind:'layers', summary:'Apply least privilege and secure network boundaries.', explain:'Cloud identity and access management controls who can perform actions on resources. Prefer managed identities or workload identity federation over long-lived credentials when supported. Use private networking where appropriate, TLS in transit, secret stores and audit logs.', code:'Developer workflow → Federated identity → Short-lived token\n→ Least-privilege role → Target cloud resource\nMonitor access and rotate any unavoidable secrets', task:'Explain why managed identity is usually preferable to storing a cloud service principal secret in a repository.', video:'M988_fsOSWo', videoTitle:'Cloud IAM and security basics' },
  { id:'linux-1', track:'Linux & Shell', level:'Basic', title:'Linux filesystem, commands & permissions', duration:'10 min', kind:'table', summary:'Navigate servers and inspect files from the command line.', explain:'pwd shows the current directory, ls lists files, cd changes directories, and grep searches text. Linux permissions control read, write and execute access for owner, group and others. Avoid using elevated privileges unless needed.', code:'pwd\nls -la\ngrep -n "ERROR" app.log\nchmod 640 config.txt\nps aux | head', task:'Write commands to find the current directory, inspect a log file and show the running processes.', video:'sWbUDq4S6Y8', videoTitle:'Linux command line basics' },
  { id:'linux-2', track:'Linux & Shell', level:'Intermediate', title:'Shell scripts, pipes & environment variables', duration:'13 min', kind:'flow', summary:'Automate repeatable operations with small shell scripts.', explain:'Shell pipelines send one command’s output to another. Environment variables configure processes; do not print secrets into logs. Scripts should check failures, quote variable expansions and use predictable exit codes.', code:'#!/usr/bin/env bash\nset -euo pipefail\nAPP_NAME="studynest"\nprintf "Deploying %s\\n" "$APP_NAME"\n./scripts/health-check.sh', task:'Explain what set -euo pipefail helps detect in a shell script.', video:'sWbUDq4S6Y8', videoTitle:'Bash scripting essentials' },
  { id:'docker-1', track:'Docker & Containers', level:'Basic', title:'Images, containers & Dockerfiles', duration:'12 min', kind:'flow', summary:'Package an application with its runtime dependencies.', explain:'An image is a template; a container is a running instance. A Dockerfile describes how to build an image. Use small trusted base images, pin dependencies where appropriate, avoid embedding secrets, and run as a non-root user when possible.', code:'FROM node:22-alpine\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci\nCOPY . .\nRUN npm run build\nCMD ["npm", "run", "preview", "--", "--host", "0.0.0.0"]', task:'Explain why copying package files before the rest of the source can improve build caching.', video:'pg19Z8LL06w', videoTitle:'Docker for beginners' },
  { id:'docker-2', track:'Docker & Containers', level:'Intermediate', title:'Container networking, volumes & Compose', duration:'15 min', kind:'layers', summary:'Connect services and persist data outside container lifetimes.', explain:'Containers on a shared network can communicate by service name. Volumes persist data beyond a container’s lifecycle. Compose describes multi-container local environments; production deployments still need health checks, secure configuration and resource limits.', code:'services:\n  web:\n    build: .\n    ports:\n      - "8080:8080"\n    depends_on:\n      - api\n  api:\n    image: example-api:latest', task:'Explain why a database should generally store persistent data in a volume rather than only in a container writable layer.', video:'pg19Z8LL06w', videoTitle:'Docker Compose and networking' },
  { id:'git-1', track:'Git & GitHub', level:'Basic', title:'Commits, branches & pull requests', duration:'9 min', kind:'flow', summary:'Track changes and collaborate through reviewed branches.', explain:'A commit records a snapshot of changes. Branches let work proceed independently; pull requests support review and automated checks before merging. Make commits focused and avoid committing secrets or generated build artifacts unnecessarily.', code:'git switch -c feature/course-catalog\ngit add src/data.js\ngit commit -m "Add course catalog tracks"\ngit push -u origin feature/course-catalog', task:'Describe the steps you would use to submit a small feature for review without committing directly to main.', video:'RGOj5yH7evk', videoTitle:'Git and GitHub beginner guide' },
  { id:'git-2', track:'Git & GitHub', level:'Intermediate', title:'Merge conflicts, tags & release workflow', duration:'12 min', kind:'layers', summary:'Resolve parallel changes and create traceable releases.', explain:'A merge conflict occurs when Git cannot automatically reconcile changes. Inspect both versions, resolve intentionally, run tests and commit the result. Tags mark release points; release notes summarize user-visible changes and migration concerns.', code:'git fetch origin\ngit switch main\ngit pull --ff-only\ngit merge feature/course-catalog\ngit tag -a v1.1.0 -m "StudyNest 1.1.0"', task:'Explain why tests should be rerun after resolving a merge conflict.', video:'RGOj5yH7evk', videoTitle:'Git merge conflicts and releases' },
  { id:'k8s-1', track:'Kubernetes', level:'Basic', title:'Pods, deployments & services', duration:'14 min', kind:'layers', summary:'Understand core Kubernetes objects used to run containerized apps.', explain:'A Pod is the smallest deployable unit. A Deployment manages replicated Pods and rolling updates. A Service provides a stable network endpoint. Kubernetes adds orchestration complexity, so start with containers and learn cluster operations when your use case needs them.', code:'apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: web\nspec:\n  replicas: 2\n  selector:\n    matchLabels: { app: web }\n  template:\n    metadata:\n      labels: { app: web }\n    spec:\n      containers:\n        - name: web\n          image: nginx:stable', task:'Explain what a Deployment does when one of its Pods crashes.', video:'X48VuDVv0do', videoTitle:'Kubernetes basics' },
  { id:'k8s-2', track:'Kubernetes', level:'Intermediate', title:'ConfigMaps, secrets & health probes', duration:'15 min', kind:'layers', summary:'Configure workloads and let the platform detect unhealthy containers.', explain:'ConfigMaps hold non-sensitive configuration; Secrets are intended for sensitive values but still require suitable access controls and encryption. Readiness probes control traffic eligibility, liveness probes detect stuck containers, and resource requests/limits help manage scheduling and consumption.', code:'readinessProbe:\n  httpGet:\n    path: /health\n    port: 8080\n  initialDelaySeconds: 5\n  periodSeconds: 10', task:'Describe the difference between readiness and liveness probes and give an example of when each should fail.', video:'X48VuDVv0do', videoTitle:'Kubernetes configuration and probes' },

  // Advanced lessons complete the new language and platform learning paths
  { id:'java-3', track:'Java', level:'Advanced', title:'Generics, streams & exception design', duration:'18 min', kind:'layers', summary:'Write type-safe transformations and handle failures intentionally.', explain:'Generics make reusable classes and methods type-safe. Streams describe data transformations such as filter, map and collect. Use specific exceptions and preserve the original cause when translating errors at application boundaries.', code:'import java.util.List;\n\nvar scores = List.of(72, 91, 58, 84);\nvar passed = scores.stream()\n    .filter(score -> score >= 70)\n    .map(score -> score + 5)\n    .toList();\nSystem.out.println(passed);', task:'Add a stream operation that sorts the passing scores in descending order and explain why generics help prevent type errors.', video:'eIrMbAQSU34', videoTitle:'Java streams and generics' },
  { id:'javascript-3', track:'JavaScript', level:'Advanced', title:'Closures, modules & performance', duration:'17 min', kind:'layers', summary:'Structure larger JavaScript applications and avoid common performance traps.', explain:'Closures retain access to lexical variables after the outer function returns. ES modules make dependencies explicit. Avoid unnecessary DOM work, clean up event listeners, and profile before optimizing. Treat all external data as untrusted.', code:'export function createCounter() {\n  let count = 0;\n  return () => ++count;\n}\n\nconst next = createCounter();\nconsole.log(next()); // 1\nconsole.log(next()); // 2', task:'Explain why the returned function can still access count and identify one way to prevent a memory leak in a long-lived UI.', video:'W6NZfCO5SIk', videoTitle:'JavaScript closures and modules' },
  { id:'c-3', track:'C Programming', level:'Advanced', title:'Dynamic memory & defensive C', duration:'18 min', kind:'layers', summary:'Allocate and release memory safely and reason about undefined behavior.', explain:'malloc and related functions allocate memory that the program must release with free. Check allocation results, prevent buffer overflows, avoid use-after-free and double-free errors, and compile with warnings and sanitizers during development.', code:'#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int *values = malloc(3 * sizeof *values);\n    if (values == NULL) return 1;\n    values[0] = 10;\n    printf("%d\\n", values[0]);\n    free(values);\n    return 0;\n}', task:'What can go wrong if code accesses values after free(values)? Describe one tool or compiler option that helps catch memory errors.', video:'KJgsSFOSQv0', videoTitle:'C memory management' },
  { id:'htmlcss-3', track:'HTML & CSS', level:'Advanced', title:'Accessibility, design systems & CSS architecture', duration:'16 min', kind:'layers', summary:'Create reusable UI patterns that remain accessible and maintainable.', explain:'Accessible interfaces support keyboard use, visible focus, semantic structure and sufficient contrast. Design tokens centralize spacing and color decisions. Prefer component-scoped styles, responsive layouts and reduced-motion support over brittle selector chains.', code:':root { --space-3: 1rem; --focus: #2457d6; }\n.button:focus-visible { outline: 3px solid var(--focus); outline-offset: 3px; }\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; }\n}', task:'Audit a course card for keyboard navigation, focus visibility, heading order and mobile overflow.', video:'1PnVor36_40', videoTitle:'Accessible responsive UI design' },
  { id:'devops-3', track:'DevOps', level:'Advanced', title:'Release strategies, SLOs & incident response', duration:'18 min', kind:'layers', summary:'Make deployments measurable, reversible and resilient.', explain:'Blue-green and canary releases limit the impact of changes. Service-level indicators measure user-visible behavior; objectives set reliability targets. Define rollback triggers, alert on actionable symptoms, and document incident learning without blame.', code:'Release gate:\n- Build and test pass\n- Health check succeeds\n- Error rate stays within SLO\n- Latency remains acceptable\n- Roll back automatically if a guardrail fails', task:'Choose an error-rate and latency guardrail for a sample API and explain when a canary release should stop.', video:'0yWAtQ6wYNM', videoTitle:'DevOps release strategies and SRE' },
  { id:'cloud-3', track:'Cloud Fundamentals', level:'Advanced', title:'Resilience, cost controls & architecture', duration:'18 min', kind:'layers', summary:'Design cloud workloads for failure, scale and predictable cost.', explain:'Design for component failure with health checks, backups, recovery objectives and multi-zone deployment where justified. Autoscaling should follow useful signals and have limits. Budgets, tags, rightsizing and retention policies help control cost without weakening security.', code:'Architecture review:\n1. Define availability and recovery targets\n2. Identify single points of failure\n3. Test backup restoration\n4. Add budget alerts and resource tags\n5. Review scaling limits and observability', task:'Explain the difference between RTO and RPO, then list two ways to prevent an unexpected cloud bill.', video:'M988_fsOSWo', videoTitle:'Cloud architecture and reliability' },
  { id:'linux-3', track:'Linux & Shell', level:'Advanced', title:'Processes, services, logs & troubleshooting', duration:'17 min', kind:'layers', summary:'Investigate service failures using system-level signals.', explain:'Use process and resource tools to understand CPU, memory and disk pressure. systemctl manages systemd services on many distributions; journalctl reads service logs. Check recent changes, permissions, ports and dependencies before restarting repeatedly.', code:'systemctl status myapp\njournalctl -u myapp --since "15 minutes ago"\nfree -h\ndf -h\nss -lntp', task:'A service is down and its disk is full. Name the first checks you would perform and explain why deleting logs blindly can be risky.', video:'sWbUDq4S6Y8', videoTitle:'Linux server troubleshooting' },
  { id:'docker-3', track:'Docker & Containers', level:'Advanced', title:'Secure, small and reproducible images', duration:'18 min', kind:'layers', summary:'Reduce image risk and improve build repeatability.', explain:'Multi-stage builds separate build tools from runtime artifacts. Pin trusted base images, scan dependencies, avoid secrets in layers, use a non-root user, and apply .dockerignore. Prefer immutable image tags or digests in controlled deployments.', code:'FROM node:22-alpine AS build\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci\nCOPY . .\nRUN npm run build\n\nFROM nginx:stable-alpine\nCOPY --from=build /app/dist /usr/share/nginx/html\nUSER nginx', task:'Explain how multi-stage builds reduce the runtime image and name two checks to add before publishing an image.', video:'pg19Z8LL06w', videoTitle:'Docker multi-stage builds and security' },
  { id:'git-3', track:'Git & GitHub', level:'Advanced', title:'CI workflows, protected branches & safe releases', duration:'16 min', kind:'layers', summary:'Automate quality gates while protecting deployment credentials.', explain:'CI workflows should run repeatable lint, test and build checks. Protect important branches with reviews and required checks. Prefer short-lived workload identity federation over long-lived cloud secrets where supported, scope permissions narrowly and keep deployment environments separate.', code:'name: CI\non: [push, pull_request]\njobs:\n  checks:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with: { node-version: 22 }\n      - run: npm ci\n      - run: npm run lint\n      - run: npm run build', task:'Describe how you would prevent an unreviewed pull request from deploying to production and why CI permissions should be minimal.', video:'RGOj5yH7evk', videoTitle:'GitHub Actions CI/CD and security' },
  { id:'k8s-3', track:'Kubernetes', level:'Advanced', title:'Autoscaling, resource requests & rollout safety', duration:'19 min', kind:'layers', summary:'Keep workloads stable as demand changes and releases progress.', explain:'Resource requests help the scheduler place Pods; limits constrain resource use. Horizontal Pod Autoscaling adjusts replica counts based on metrics. Use rolling update limits, disruption budgets, observability and rollback checks. Kubernetes is useful when its orchestration benefits justify its operational overhead.', code:'apiVersion: autoscaling/v2\nkind: HorizontalPodAutoscaler\nmetadata:\n  name: web\nspec:\n  scaleTargetRef:\n    apiVersion: apps/v1\n    kind: Deployment\n    name: web\n  minReplicas: 2\n  maxReplicas: 8\n  metrics:\n    - type: Resource\n      resource:\n        name: cpu\n        target:\n          type: Utilization\n          averageUtilization: 70', task:'Explain why a Pod can be throttled or rescheduled when resource settings are poor, and name one rollout safety control.', video:'X48VuDVv0do', videoTitle:'Kubernetes autoscaling and deployments' },
  {"id":"genai-1","track":"Generative AI","level":"Basic","title":"What is Generative AI? Models, tokens & use cases","duration":"12 min","kind":"flow","summary":"Understand how generative models create new text, images, audio and code.","explain":"Generative AI learns statistical patterns from training examples and uses them to produce new content from a prompt. A language model processes text as tokens, predicts likely next tokens, and repeats that process to create a response. It does not automatically know whether an answer is true. Think of it as a capable assistant whose output still needs checking. Traditional software follows explicit rules; generative models produce probabilistic outputs.","code":"prompt = \"Explain APIs to a beginner in three bullet points.\"\n# A model converts the prompt into tokens\n# It predicts the next token repeatedly\n# The application displays the generated response\nprint(\"Review the response for accuracy before using it.\")","task":"Give three useful Generative AI use cases and one risk for each. Explain the difference between a model and the application built around it."},
  {"id":"genai-2","track":"Generative AI","level":"Basic","title":"Prompt engineering: clear instructions and examples","duration":"14 min","kind":"layers","summary":"Write prompts that specify role, task, context, constraints and output format.","explain":"A prompt is the instruction and context provided to a model. Strong prompts state the goal, audience, relevant facts, constraints, and desired format. Few-shot prompting supplies examples of the desired input-output pattern. Iterate using representative test cases instead of assuming one prompt works for every situation. Never put private data or secrets into a prompt unless the service and policy explicitly allow it.","code":"prompt = \"\"\"Task: Explain a Python dictionary.\nAudience: Complete beginner.\nContext: The learner knows variables and lists.\nConstraints: Use a simple analogy and one short example.\nFormat: Definition, example, common mistake, mini-exercise.\n\"\"\"\nprint(prompt)","task":"Rewrite a vague prompt—“teach me AI”—as a clear prompt for a beginner, including context, constraints and a requested output format."},
  {"id":"genai-3","track":"Generative AI","level":"Basic","title":"Using an LLM API safely: inputs, outputs and errors","duration":"16 min","kind":"flow","summary":"Learn the shape of a model request and the safety checks around it.","explain":"An LLM application typically sends instructions and user content to a provider API, receives generated output, then validates and presents it. Production code needs timeouts, bounded retries, rate-limit handling, structured logging without sensitive prompts, and graceful error messages. Store provider keys on a trusted backend in environment variables or a secret manager—not in browser code or a public repository. This example shows a provider-neutral request shape, not a live API call.","code":"request = {\n    \"model\": \"your-approved-model\",\n    \"messages\": [\n        {\"role\": \"system\", \"content\": \"Explain concepts accurately.\"},\n        {\"role\": \"user\", \"content\": \"What is an API?\"}\n    ],\n    \"temperature\": 0.2\n}\n# Send from a trusted server using the provider SDK\n# Validate the response and handle timeouts / rate limits","task":"Draw the request-response flow for a chatbot and list four failure cases your backend should handle."},
  {"id":"genai-4","track":"Generative AI","level":"Intermediate","title":"Embeddings, semantic search and vector databases","duration":"18 min","kind":"layers","summary":"Learn how text can be represented as vectors to find meaning-related content.","explain":"An embedding model maps text into a numeric vector. Texts with similar meanings can be close in the embedding space, making semantic search useful when exact keywords differ. A typical pipeline chunks documents, embeds each chunk, stores vectors with metadata, embeds a query, retrieves nearest matches, and optionally reranks them. Chunk size, overlap, metadata filters and evaluation strongly affect retrieval quality.","code":"documents = [\n    \"StudyNest teaches Python basics.\",\n    \"StudyNest includes AI learning paths.\",\n    \"Learners can track course progress.\"\n]\n# vectors = embedding_model.embed(documents)\n# vector_store.upsert(vectors, metadata=source_metadata)\nquery = \"Where can I learn about artificial intelligence?\"\n# query_vector = embedding_model.embed([query])[0]\n# matches = vector_store.search(query_vector, top_k=3)","task":"Design a small semantic-search dataset for a student handbook. Name useful metadata fields and explain why exact keyword search may miss relevant results."},
  {"id":"genai-5","track":"Generative AI","level":"Intermediate","title":"RAG: ground answers in trusted documents","duration":"20 min","kind":"layers","summary":"Build the mental model for Retrieval-Augmented Generation and citations.","explain":"Retrieval-Augmented Generation (RAG) retrieves relevant source passages and provides them to a model alongside the question. The model is instructed to answer from that evidence and say when the evidence is insufficient. RAG can improve grounding and freshness, but it does not guarantee correctness: retrieval may miss evidence, sources may conflict, and the model may still misinterpret context. Evaluate retrieval and answer quality separately, and show citations that link back to source documents.","code":"question = \"What is the course completion policy?\"\ncontext = [\n    {\"source\": \"handbook.md#completion\", \"text\": \"Learners mark each lesson complete.\"}\n]\nprompt = f\"\"\"Answer using only the supplied context.\nIf the answer is not present, say you do not know.\nQuestion: {question}\nContext: {context}\nInclude the source reference in your answer.\n\"\"\"\n# response = llm.generate(prompt)","task":"Create a RAG flow with ingestion, chunking, embeddings, retrieval, generation and citations. Identify two ways you would test whether retrieved passages actually support answers."},
  {"id":"genai-6","track":"Generative AI","level":"Intermediate","title":"Structured output, tool calls and validation","duration":"18 min","kind":"table","summary":"Turn free-form model text into data your application can validate.","explain":"Applications often need predictable JSON or a schema-constrained response rather than prose. Request a schema when the provider supports it, then validate the returned data again in your own application. A model proposing a tool call is not proof that the call is safe. Validate the tool name, arguments, permissions and business rules before execution. Reject unexpected fields and handle malformed output.","code":"from pydantic import BaseModel, Field\n\nclass StudyPlan(BaseModel):\n    topic: str\n    minutes: int = Field(ge=5, le=180)\n    beginner_friendly: bool\n\ncandidate_output = {\n    \"topic\": \"Prompt engineering\",\n    \"minutes\": 30,\n    \"beginner_friendly\": True\n}\nplan = StudyPlan.model_validate(candidate_output)\nprint(plan.topic, plan.minutes)","task":"Define a schema for an AI-generated quiz question. Include the question, four options, a valid answer index and an explanation. Describe how invalid output should be handled."},
  {"id":"genai-7","track":"Generative AI","level":"Advanced","title":"Evaluation, hallucinations, safety and red teaming","duration":"22 min","kind":"layers","summary":"Measure quality and design safeguards for real users.","explain":"A reliable GenAI system needs a representative evaluation set, not only a few impressive examples. Measure task correctness, groundedness, relevance, refusal behavior, latency, cost and user impact. Test adversarial prompts, prompt injection, private-data leakage, biased outcomes and unsafe requests. Use deterministic checks where possible, human review for high-impact cases, and monitoring for regressions. Guardrails reduce risk but do not replace access control, secure system design or clear product boundaries.","code":"evaluation_case = {\n    \"question\": \"Summarize this policy and cite the source.\",\n    \"expected_source\": \"policy.md#section-2\",\n    \"checks\": [\n        \"claims_supported_by_source\",\n        \"citation_is_valid\",\n        \"no_sensitive_data_leaked\",\n        \"uncertainty_is_stated\"\n    ]\n}\n# Run the same evaluation set after each prompt or model change","task":"Create five evaluation cases for a course-help chatbot, including one prompt-injection attempt and one question with no supporting source. Define pass/fail criteria."},
  {"id":"genai-8","track":"Generative AI","level":"Advanced","title":"Production GenAI architecture, cost and observability","duration":"24 min","kind":"layers","summary":"Plan a secure, observable and cost-aware AI feature from prototype to production.","explain":"A production architecture separates the UI, trusted backend, model provider, retrieval layer and observability. Add authentication and authorization before retrieving private content; use tenant-aware filters, bounded input/output sizes, timeouts, rate limits and request budgets. Track latency, token usage, retrieval quality, error rates and feedback without logging secrets. Cache only when data privacy and freshness allow it. Use model fallbacks carefully, version prompts, and define rollback criteria.","code":"def estimate_request_cost(input_tokens, output_tokens, input_rate, output_rate):\n    input_cost = input_tokens * input_rate / 1_000_000\n    output_cost = output_tokens * output_rate / 1_000_000\n    return input_cost + output_cost\n\n# Use current provider pricing in the real application\ncost = estimate_request_cost(1200, 300, 1.0, 4.0)\nprint(f\"Estimated request cost: ${cost:.6f}\")","task":"Sketch a production architecture for an AI study assistant. Include secrets management, user access controls, monitoring, rate limiting, evaluation and a rollback strategy."},
  {"id":"agentic-1","track":"Agentic AI","level":"Basic","title":"What is an AI agent? Model, tools, state and goal","duration":"14 min","kind":"flow","summary":"Distinguish a chatbot response from an agent that can choose and use tools.","explain":"An AI agent is a system that uses a model to decide next steps toward a goal, often by selecting tools, observing results and continuing within limits. A model alone does not automatically have access to the internet, files or business systems; the surrounding application grants specific tools. An agent loop usually includes instructions, current state, a model decision, a validated action, a tool result and a stop condition. Begin with narrow, read-only tools before granting actions that change data.","code":"state = {\"goal\": \"Find beginner Python lessons\", \"steps\": []}\n# 1. Ask the model to choose an allowed next action\n# 2. Validate the proposed tool and arguments\n# 3. Run the tool with least-privilege access\n# 4. Add the result to state\n# 5. Stop when the goal is met or a limit is reached\nprint(state[\"goal\"])","task":"Explain the difference between a normal chatbot and an agent. Give one safe read-only tool and one tool that would require extra approval."},
  {"id":"agentic-2","track":"Agentic AI","level":"Basic","title":"Tool calling and typed tool contracts","duration":"16 min","kind":"table","summary":"Define tools with clear names, descriptions, schemas and bounded permissions.","explain":"A tool is an application function an agent may request. The model proposes a tool name and arguments; the application validates the request and performs the operation. Tool descriptions should be specific, argument schemas should be strict, and errors should be returned in a predictable format. Never execute arbitrary model-generated code or trust tool arguments without validation. Keep credentials and authorization checks in the tool implementation.","code":"def search_courses(query: str, limit: int = 5) -> dict:\n    \"\"\"Search public course titles; limit is restricted to 1–10.\"\"\"\n    if not query.strip():\n        return {\"error\": \"query is required\"}\n    if not 1 <= limit <= 10:\n        return {\"error\": \"limit must be between 1 and 10\"}\n    # Replace with a real, permission-checked search operation\n    return {\"query\": query, \"limit\": limit, \"results\": []}\n\nprint(search_courses(\"Python basics\", 3))","task":"Design a typed search tool contract with required and optional arguments. List validation rules and explain why the model should not receive direct database credentials."},
  {"id":"agentic-3","track":"Agentic AI","level":"Basic","title":"Agent loops, observations and stop conditions","duration":"18 min","kind":"flow","summary":"Understand the repeated decide-act-observe cycle and why loops need limits.","explain":"A simple agent loop sends the goal and state to a model, interprets the requested next action, runs an allowed tool, records the observation and asks the model what to do next. Without safeguards, loops can repeat forever, waste tokens or take unintended actions. Set a maximum number of steps, total time and cost budget; detect repeated tool calls; and stop when the goal is complete or a human must decide.","code":"MAX_STEPS = 5\nobservations = []\nfor step in range(MAX_STEPS):\n    # action = model.choose_action(goal, observations)\n    # result = run_validated_tool(action)\n    result = {\"step\": step + 1, \"status\": \"example-only\"}\n    observations.append(result)\n    if result.get(\"status\") == \"complete\":\n        break\nelse:\n    print(\"Stop safely: step budget reached\")","task":"Write pseudocode for an agent that searches course content and summarizes the best matches. Include a maximum step count, a repeated-action check and a clear completion condition."},
  {"id":"agentic-4","track":"Agentic AI","level":"Intermediate","title":"Planning, task decomposition and memory","duration":"20 min","kind":"layers","summary":"Break a goal into manageable steps and preserve only useful state.","explain":"Planning decomposes a broad goal into smaller tasks with dependencies and completion checks. Short-term state can track the current run; persistent memory may store user-approved preferences or task outcomes across sessions. Memory should be scoped to the correct user, minimized, editable and deletable. Avoid treating untrusted retrieved content as instructions. Plans should be revised when tool results contradict assumptions, and each step should have a measurable output.","code":"plan = [\n    {\"step\": 1, \"task\": \"Find relevant course lessons\", \"done\": False},\n    {\"step\": 2, \"task\": \"Group lessons by difficulty\", \"done\": False},\n    {\"step\": 3, \"task\": \"Create a 7-day schedule\", \"done\": False},\n]\nfor item in plan:\n    print(item[\"step\"], item[\"task\"])\n# Mark a step complete only after checking its result","task":"Break “help me prepare for a Python interview in one week” into five tasks with dependencies and measurable completion checks."},
  {"id":"agentic-5","track":"Agentic AI","level":"Intermediate","title":"RAG-powered agents and trusted knowledge tools","duration":"20 min","kind":"layers","summary":"Combine document retrieval with agent decisions without confusing data for instructions.","explain":"A RAG agent can search approved knowledge sources, inspect citations and use the evidence to answer a question or decide the next step. Retrieved documents are data, not trusted system instructions: they may contain malicious prompt injection or stale guidance. Enforce permissions before retrieval, label source content clearly, and require the final answer to cite the evidence used. Separate search from privileged actions, and do not let a document grant itself extra permissions.","code":"def retrieve_policy(question, user_scope):\n    # Filter documents by permissions before similarity search\n    return [\n        {\"source\": \"course-guide.md#basics\", \"text\": \"Start with fundamentals.\"}\n    ]\n\ncontext = retrieve_policy(\"How should I start?\", user_scope=\"learner-123\")\n# Give retrieved text to the model as untrusted reference material\n# Ask for an answer grounded in the returned passages","task":"Describe how you would stop a malicious paragraph inside a retrieved document from overriding an agent's system instructions. Include permission filtering and citation checks."},
  {"id":"agentic-6","track":"Agentic AI","level":"Intermediate","title":"Multi-agent patterns, handoffs and coordination","duration":"22 min","kind":"table","summary":"Understand when separate specialized agents help—and when they add needless complexity.","explain":"A multi-agent design may separate roles such as researcher, planner and reviewer, with explicit input/output contracts and a coordinator. It can help when tasks are naturally separable, but introduces communication overhead, nondeterminism, duplicated work and more failure modes. Define who owns the final decision, how disagreements are handled, what data each role can access, and when the workflow stops. A single agent with well-designed tools is often simpler and easier to evaluate.","code":"workflow = [\n    {\"role\": \"researcher\", \"output\": \"sources and evidence\"},\n    {\"role\": \"planner\", \"output\": \"ordered learning plan\"},\n    {\"role\": \"reviewer\", \"output\": \"checks and gaps\"},\n]\nfor stage in workflow:\n    print(stage[\"role\"], \"must return:\", stage[\"output\"])\n# Coordinator validates each handoff before the next stage","task":"Design a three-role agent workflow for generating a learning plan. Specify each role's input, output, permissions and how the coordinator handles conflicting recommendations."},
  {"id":"agentic-7","track":"Agentic AI","level":"Advanced","title":"Human approval, durable workflows and failure recovery","duration":"24 min","kind":"layers","summary":"Make long-running agent work resumable, auditable and safe around consequential actions.","explain":"Real workflows may pause for approval, wait for an external system, or recover after a timeout. Persist a versioned state machine with explicit statuses, deadlines, retry policies and audit events. Use idempotency keys so retries do not duplicate side effects. Ask for human approval before sending messages, spending money, deleting data or changing access. A timeout does not prove that a remote action failed; reconcile its status before retrying.","code":"workflow_state = {\n    \"status\": \"awaiting_approval\",\n    \"proposed_action\": \"publish_study_plan\",\n    \"approval_required\": True,\n    \"idempotency_key\": \"plan-2026-001\"\n}\nif workflow_state[\"approval_required\"]:\n    print(\"Pause: request explicit human approval\")\n# Persist state and resume only after verified approval","task":"Create a state diagram for an agent that drafts an email but must wait for approval before sending it. Include timeout handling, idempotency and audit logging."},
  {"id":"agentic-8","track":"Agentic AI","level":"Advanced","title":"Agent evaluation, observability and production security","duration":"26 min","kind":"layers","summary":"Test complete trajectories, permissions, costs and recovery—not just the final text.","explain":"Agent evaluation must inspect the whole trajectory: chosen tools, arguments, observations, retries, policy compliance, task success and stopping behavior. Test prompt injection, tool errors, repeated calls, unavailable services, authorization failures and ambiguous goals. Record trace IDs, tool latency, token/cost budgets and redacted events. Apply least privilege, per-tool allowlists, sandboxing where relevant, approval gates and emergency stop controls. Benchmark against deterministic workflows and use an agent only where its flexibility earns its complexity.","code":"agent_test = {\n    \"goal\": \"Find three beginner AI lessons\",\n    \"allowed_tools\": [\"search_courses\"],\n    \"max_steps\": 5,\n    \"must_not\": [\"read_private_notes\", \"modify_account\"],\n    \"success_checks\": [\"three_results\", \"relevant\", \"no_permission_violation\"]\n}\n# Evaluate action traces as well as the final response\n# Alert on repeated calls, budget overruns and denied access","task":"Write a 6-case test plan for a production agent, including prompt injection, tool timeout, permission denial, duplicate action and cost-limit scenarios. State the expected safe behavior for each."},
  {"id":"java-4","track":"Java","level":"Basic","title":"Primitive types, operators & casting","duration":"12 min","kind":"flow","summary":"Choose numeric, character and boolean types and understand conversion.","explain":"Choose numeric, character and boolean types and understand conversion. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"int quantity = 3;\ndouble price = 19.5;\nboolean available = quantity > 0;\ndouble total = quantity * price;\nSystem.out.println(total);","task":"Create a price calculator that uses quantity, unit price and a boolean availability check."},
  {"id":"java-5","track":"Java","level":"Basic","title":"Arrays, loops & methods","duration":"12 min","kind":"flow","summary":"Store same-type values and separate reusable logic into methods.","explain":"Store same-type values and separate reusable logic into methods. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"static int sum(int[] values) {\n    int total = 0;\n    for (int value : values) total += value;\n    return total;\n}\nSystem.out.println(sum(new int[]{2, 4, 6}));","task":"Write a method that returns the largest number in an integer array, including a documented empty-array policy."},
  {"id":"java-6","track":"Java","level":"Intermediate","title":"Collections, maps & generics","duration":"12 min","kind":"layers","summary":"Select List, Set and Map based on ordering, uniqueness and lookup needs.","explain":"Select List, Set and Map based on ordering, uniqueness and lookup needs. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"import java.util.*;\nList<String> topics = new ArrayList<>();\ntopics.add(\"Java\");\ntopics.add(\"SQL\");\nMap<String, Integer> minutes = new HashMap<>();\nminutes.put(\"Java\", 30);\nSystem.out.println(minutes.get(\"Java\"));","task":"Store course durations in a Map and print only courses longer than 20 minutes."},
  {"id":"java-7","track":"Java","level":"Intermediate","title":"Exceptions, files & resource management","duration":"12 min","kind":"layers","summary":"Handle expected failures and close files reliably with try-with-resources.","explain":"Handle expected failures and close files reliably with try-with-resources. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"try (var reader = java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(\"notes.txt\"))) {\n    String line;\n    while ((line = reader.readLine()) != null) {\n        System.out.println(line);\n    }\n} catch (java.io.IOException ex) {\n    System.err.println(\"Could not read notes: \" + ex.getMessage());\n}","task":"Explain why try-with-resources is safer than manually closing a file reader."},
  {"id":"java-8","track":"Java","level":"Advanced","title":"Streams, testing & application design","duration":"12 min","kind":"table","summary":"Use stream pipelines carefully and test behavior at boundaries.","explain":"Use stream pipelines carefully and test behavior at boundaries. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"List<Integer> scores = List.of(72, 91, 58, 84);\nList<Integer> passing = scores.stream()\n    .filter(score -> score >= 60)\n    .sorted()\n    .toList();\nSystem.out.println(passing);","task":"Add tests for empty input, boundary scores and duplicate values; explain when a normal loop may be clearer."},
  {"id":"js-4","track":"JavaScript","level":"Basic","title":"Objects, destructuring & array methods","duration":"12 min","kind":"flow","summary":"Represent structured records and transform arrays without manual index loops.","explain":"Represent structured records and transform arrays without manual index loops. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"const learner = { name: 'Asha', minutes: 45 };\nconst { name, minutes } = learner;\nconst topics = ['JS', 'SQL', 'Python'];\nconst labels = topics.map((topic) => topic.toUpperCase());\nconsole.log(name, minutes, labels);","task":"Create an array of course objects and use filter to show courses longer than 30 minutes."},
  {"id":"js-5","track":"JavaScript","level":"Basic","title":"DOM events, forms & validation","duration":"12 min","kind":"flow","summary":"Respond to user actions and validate form input before processing it.","explain":"Respond to user actions and validate form input before processing it. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"const form = document.querySelector('#signup');\nform.addEventListener('submit', (event) => {\n  event.preventDefault();\n  const email = form.elements.email.value.trim();\n  if (!email.includes('@')) {\n    form.elements.email.setCustomValidity('Enter a valid email');\n    form.reportValidity();\n    return;\n  }\n  console.log('Form ready to submit');\n});","task":"Build a form that rejects empty names and invalid email addresses. Explain why client validation is not enough for security."},
  {"id":"js-6","track":"JavaScript","level":"Intermediate","title":"Modules, npm & error handling","duration":"12 min","kind":"layers","summary":"Organize application code into modules and handle rejected promises.","explain":"Organize application code into modules and handle rejected promises. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"// courses.js\nexport function findCourse(courses, id) {\n  return courses.find((course) => course.id === id) ?? null;\n}\n\n// app.js\nimport { findCourse } from './courses.js';\ntry {\n  console.log(findCourse([], 1));\n} catch (error) {\n  console.error('Unexpected failure', error);\n}","task":"Split a small app into data and UI modules, then document how to run and test it."},
  {"id":"js-7","track":"JavaScript","level":"Intermediate","title":"Fetch APIs, loading states & retries","duration":"12 min","kind":"layers","summary":"Call an HTTP API and represent loading, success and failure explicitly.","explain":"Call an HTTP API and represent loading, success and failure explicitly. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"async function loadCourses() {\n  const response = await fetch('/api/courses');\n  if (!response.ok) throw new Error(`HTTP ${response.status}`);\n  return response.json();\n}\nloadCourses()\n  .then((courses) => console.log(courses))\n  .catch((error) => console.error('Could not load courses', error));","task":"Add a visible loading state and an error message. Explain why not every failed request should be retried."},
  {"id":"js-8","track":"JavaScript","level":"Advanced","title":"Testing, accessibility & performance","duration":"12 min","kind":"table","summary":"Test behavior and avoid unnecessary work in browser applications.","explain":"Test behavior and avoid unnecessary work in browser applications. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"export function average(values) {\n  if (values.length === 0) return null;\n  return values.reduce((sum, value) => sum + value, 0) / values.length;\n}\n// Test normal, empty and boundary inputs with your test runner","task":"Write unit tests for average and audit a form for keyboard access, labels and clear focus indicators."},
  {"id":"c-4","track":"C Programming","level":"Basic","title":"Operators, conditions & loops","duration":"12 min","kind":"flow","summary":"Control program flow and validate user input before using it.","explain":"Control program flow and validate user input before using it. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"#include <stdio.h>\nint main(void) {\n    int score = 76;\n    if (score >= 60) printf(\"Pass\\n\");\n    for (int i = 1; i <= 3; i++) printf(\"Attempt %d\\n\", i);\n    return 0;\n}","task":"Extend the program to classify a score and reject values outside the allowed range."},
  {"id":"c-5","track":"C Programming","level":"Basic","title":"Functions, arrays & strings","duration":"12 min","kind":"flow","summary":"Use functions to isolate logic and remember that C strings end with a null byte.","explain":"Use functions to isolate logic and remember that C strings end with a null byte. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"#include <stdio.h>\nint sum(const int values[], size_t count) {\n    int total = 0;\n    for (size_t i = 0; i < count; i++) total += values[i];\n    return total;\n}\nint main(void) {\n    int scores[] = {70, 80, 90};\n    printf(\"%d\\n\", sum(scores, 3));\n    return 0;\n}","task":"Write a function to count characters in a string without reading past its terminating null byte."},
  {"id":"c-6","track":"C Programming","level":"Intermediate","title":"Structs, pointers & const correctness","duration":"12 min","kind":"layers","summary":"Group related fields in a struct and use pointers with clear ownership rules.","explain":"Group related fields in a struct and use pointers with clear ownership rules. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"#include <stdio.h>\ntypedef struct { const char *name; int score; } Learner;\nvoid print_score(const Learner *learner) {\n    if (learner != NULL) printf(\"%s: %d\\n\", learner->name, learner->score);\n}\nint main(void) {\n    Learner a = {\"Asha\", 88};\n    print_score(&a);\n    return 0;\n}","task":"Explain the difference between a struct value, its address and a pointer to const data."},
  {"id":"c-7","track":"C Programming","level":"Intermediate","title":"Header files, compilation & debugging","duration":"12 min","kind":"layers","summary":"Separate declarations from implementation and compile with useful warnings.","explain":"Separate declarations from implementation and compile with useful warnings. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"/* Compile example: cc -std=c11 -Wall -Wextra -Wpedantic main.c learner.c -o learner */\n/* learner.h declares public functions */\n/* learner.c implements them */\n/* main.c calls the public interface */","task":"Split a small program into a header and two source files; resolve one compiler warning."},
  {"id":"c-8","track":"C Programming","level":"Advanced","title":"Memory ownership, sanitizers & defensive code","duration":"12 min","kind":"table","summary":"Define who owns allocated memory and test for invalid access.","explain":"Define who owns allocated memory and test for invalid access. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"#include <stdlib.h>\nint *make_scores(size_t count) {\n    if (count == 0 || count > SIZE_MAX / sizeof(int)) return NULL;\n    return calloc(count, sizeof(int));\n}\n/* Caller checks the result and calls free() exactly once. */","task":"Review a C function for leaks, double frees, use-after-free and integer-overflow risks."},
  {"id":"web-4","track":"HTML & CSS","level":"Basic","title":"Links, images, lists & forms","duration":"12 min","kind":"flow","summary":"Use semantic elements and provide useful text alternatives.","explain":"Use semantic elements and provide useful text alternatives. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"<main>\n  <h1>Study plan</h1>\n  <p>Choose a topic to continue learning.</p>\n  <img src=\"study-desk.jpg\" alt=\"Notebook and laptop on a desk\">\n  <a href=\"/courses\">Browse courses</a>\n</main>","task":"Build a semantic course overview with headings, a list of topics, a descriptive image alt and a clear link."},
  {"id":"web-5","track":"HTML & CSS","level":"Basic","title":"CSS selectors, cascade & box model","duration":"12 min","kind":"flow","summary":"Understand how rules target elements and how padding, border and margin affect layout.","explain":"Understand how rules target elements and how padding, border and margin affect layout. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":".course-card {\n  box-sizing: border-box;\n  padding: 1rem;\n  border: 1px solid #d7dce2;\n  margin-block: 0.75rem;\n  border-radius: 0.75rem;\n}","task":"Use browser developer tools to explain why a card's final size differs from its content width."},
  {"id":"web-6","track":"HTML & CSS","level":"Intermediate","title":"Flexbox, Grid & responsive design","duration":"12 min","kind":"layers","summary":"Build layouts that adapt to narrow and wide screens.","explain":"Build layouts that adapt to narrow and wide screens. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":".course-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr));\n  gap: 1rem;\n}\nimg { max-width: 100%; height: auto; }","task":"Create a responsive course grid and test it at mobile, tablet and desktop widths."},
  {"id":"web-7","track":"HTML & CSS","level":"Intermediate","title":"Accessible interaction & design tokens","duration":"12 min","kind":"layers","summary":"Make interactive controls usable by keyboard and maintain consistent design.","explain":"Make interactive controls usable by keyboard and maintain consistent design. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":":root { --space: 1rem; --focus: #2458d3; }\n.button:focus-visible {\n  outline: 3px solid var(--focus);\n  outline-offset: 3px;\n}\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { scroll-behavior: auto !important; }\n}","task":"Audit a page for contrast, keyboard navigation, focus visibility and reduced-motion preferences."},
  {"id":"web-8","track":"HTML & CSS","level":"Advanced","title":"CSS architecture, performance & browser testing","duration":"12 min","kind":"table","summary":"Organize styles predictably and verify behavior across browsers.","explain":"Organize styles predictably and verify behavior across browsers. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"/* Component-scoped naming keeps styles predictable. */\n.course-card__title { margin: 0; }\n.course-card--featured { border-width: 2px; }\n@supports (display: grid) {\n  .course-grid { display: grid; }\n}","task":"Refactor duplicated styles into tokens and reusable component classes, then record cross-browser test cases."},
  {"id":"devops-4","track":"DevOps","level":"Basic","title":"Git workflow, reviews & small changes","duration":"12 min","kind":"flow","summary":"Use branches and reviewable changes to keep software delivery controlled.","explain":"Use branches and reviewable changes to keep software delivery controlled. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"git switch -c feature/course-search\ngit status\ngit add src/\ngit commit -m \"Add course search\"\ngit push -u origin feature/course-search","task":"Describe the steps from a feature branch to a reviewed pull request and merged change."},
  {"id":"devops-5","track":"DevOps","level":"Basic","title":"Build, test and deployment pipeline","duration":"12 min","kind":"flow","summary":"Automate repeatable quality checks before publishing an artifact.","explain":"Automate repeatable quality checks before publishing an artifact. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"name: CI\non: [push, pull_request]\njobs:\n  verify:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 22\n      - run: npm ci\n      - run: npm run lint\n      - run: npm run build","task":"Add a test step and explain why a locked dependency install is preferred in CI."},
  {"id":"devops-6","track":"DevOps","level":"Intermediate","title":"Infrastructure as code & configuration","duration":"12 min","kind":"layers","summary":"Declare repeatable infrastructure and keep environment configuration separate from source.","explain":"Declare repeatable infrastructure and keep environment configuration separate from source. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"# Example Terraform shape\nresource \"azurerm_resource_group\" \"app\" {\n  name     = \"rg-study-example\"\n  location = \"Central India\"\n}\n# Keep secrets in a secret manager, not in committed tfvars.","task":"Explain plan/apply, state files, environment separation and secret handling in infrastructure as code."},
  {"id":"devops-7","track":"DevOps","level":"Intermediate","title":"Monitoring, logs & incident response","duration":"12 min","kind":"layers","summary":"Use signals to find failures and reduce recovery time.","explain":"Use signals to find failures and reduce recovery time. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"# Example operational checks\ncurl -fsS https://example.org/health\n# Track request rate, error rate and latency.\n# Correlate logs with a request or trace ID.\n# Define an alert and an owner for each actionable symptom.","task":"Write a small incident runbook for a failing API: detection, triage, mitigation, communication and follow-up."},
  {"id":"devops-8","track":"DevOps","level":"Advanced","title":"Release strategies, SLOs & supply-chain security","duration":"12 min","kind":"table","summary":"Reduce deployment risk and measure reliability with service objectives.","explain":"Reduce deployment risk and measure reliability with service objectives. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"# Progressive release checklist\n# 1. Verify artifact and dependency provenance\n# 2. Deploy to a small traffic slice\n# 3. Compare error rate and latency to baseline\n# 4. Roll back automatically when guardrails fail","task":"Compare rolling, blue-green and canary releases. Define an SLO and a rollback signal."},
  {"id":"cloud-4","track":"Cloud Fundamentals","level":"Basic","title":"Compute, storage, networking & managed services","duration":"12 min","kind":"flow","summary":"Choose services based on the workload and operational responsibility.","explain":"Choose services based on the workload and operational responsibility. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"# Example architecture\n# Browser -> HTTPS frontend -> API service -> managed database\n# Object storage holds uploaded files.\n# Identity and network rules restrict every connection.","task":"Draw a three-tier app and explain which parts you would manage yourself versus use as managed services."},
  {"id":"cloud-5","track":"Cloud Fundamentals","level":"Basic","title":"Regions, availability zones & shared responsibility","duration":"12 min","kind":"flow","summary":"Understand failure domains and which security tasks belong to the provider or customer.","explain":"Understand failure domains and which security tasks belong to the provider or customer. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"# Resilience checklist\n# - Select supported region(s)\n# - Separate resources by environment\n# - Back up stateful data\n# - Test restoration, not just backup creation","task":"Give examples of provider responsibilities and customer responsibilities for a managed database."},
  {"id":"cloud-6","track":"Cloud Fundamentals","level":"Intermediate","title":"Identity, networking & secret management","duration":"12 min","kind":"layers","summary":"Apply least privilege and restrict communication paths.","explain":"Apply least privilege and restrict communication paths. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"# Principle of least privilege\n# - Assign a workload identity\n# - Grant only required resource actions\n# - Prefer private networking for sensitive services\n# - Retrieve secrets from a managed vault","task":"Create a permission matrix for a web app, deployment workflow and database. Minimize each role's access."},
  {"id":"cloud-7","track":"Cloud Fundamentals","level":"Intermediate","title":"Scaling, backups & disaster recovery","duration":"12 min","kind":"layers","summary":"Plan capacity and test recovery objectives against business needs.","explain":"Plan capacity and test recovery objectives against business needs. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"# Define recovery targets\nRPO = \"maximum acceptable data loss window\"\nRTO = \"maximum acceptable recovery time\"\n# Test a restore and measure actual recovery time.","task":"Propose RPO and RTO for a student learning app and describe how you would test them."},
  {"id":"cloud-8","track":"Cloud Fundamentals","level":"Advanced","title":"Cloud architecture, cost & governance","duration":"12 min","kind":"table","summary":"Balance reliability, security and cost with measurable controls.","explain":"Balance reliability, security and cost with measurable controls. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"# Monthly cost review\n# - Tag resources by owner and environment\n# - Alert on budget thresholds\n# - Remove unused resources\n# - Review network egress and idle compute\n# - Verify resilience before downsizing","task":"Create an architecture review checklist covering availability, security, cost, compliance and operations."},
  {"id":"linux-4","track":"Linux & Shell","level":"Basic","title":"Files, search, pipes & text processing","duration":"12 min","kind":"flow","summary":"Combine small command-line tools to inspect data efficiently.","explain":"Combine small command-line tools to inspect data efficiently. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"find . -type f -name '*.log'\ngrep -n 'ERROR' app.log | head -20\nwc -l app.log\ncut -d' ' -f1 app.log | sort | uniq -c","task":"Write a pipeline that counts error lines in a log and explain what each command contributes."},
  {"id":"linux-5","track":"Linux & Shell","level":"Basic","title":"Users, permissions & safe file operations","duration":"12 min","kind":"flow","summary":"Understand owner/group/other permissions and avoid destructive commands.","explain":"Understand owner/group/other permissions and avoid destructive commands. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"ls -l deploy.sh\nchmod u+x deploy.sh\nid\n# Preview matches before deleting or changing files.","task":"Explain rwx permissions and give an example of why blindly using chmod 777 is unsafe."},
  {"id":"linux-6","track":"Linux & Shell","level":"Intermediate","title":"Shell scripts, arguments & exit codes","duration":"12 min","kind":"layers","summary":"Make scripts repeatable and stop when a required command fails.","explain":"Make scripts repeatable and stop when a required command fails. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"#!/usr/bin/env bash\nset -euo pipefail\nif [[ $# -ne 1 ]]; then\n  echo \"Usage: $0 FILE\" >&2\n  exit 2\nfi\n[[ -f \"$1\" ]] || { echo \"File not found\" >&2; exit 1; }\nwc -l -- \"$1\"","task":"Add logging and safe argument validation to a script that checks a directory for missing files."},
  {"id":"linux-7","track":"Linux & Shell","level":"Intermediate","title":"Processes, services, ports & logs","duration":"12 min","kind":"layers","summary":"Inspect running processes and services using the correct system tools.","explain":"Inspect running processes and services using the correct system tools. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"ps aux | head\nsystemctl status nginx\njournalctl -u nginx --since '30 minutes ago'\nss -ltnp","task":"Write a troubleshooting checklist for an app that is running but cannot be reached over HTTP."},
  {"id":"linux-8","track":"Linux & Shell","level":"Advanced","title":"Permissions hardening, scheduling & troubleshooting","duration":"12 min","kind":"table","summary":"Automate recurring tasks with logs, least privilege and observable outcomes.","explain":"Automate recurring tasks with logs, least privilege and observable outcomes. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"# Example cron entry: run a script every day at 02:15\n15 2 * * * /usr/local/bin/backup-check.sh >> /var/log/backup-check.log 2>&1\n# Use absolute paths and monitor the exit status.","task":"Design a scheduled health check that logs results, avoids overlapping runs and alerts on repeated failures."},
  {"id":"docker-4","track":"Docker & Containers","level":"Basic","title":"Dockerfile layers, build context & .dockerignore","duration":"12 min","kind":"flow","summary":"Create reproducible images and avoid copying local secrets or build output.","explain":"Create reproducible images and avoid copying local secrets or build output. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"FROM node:22-alpine\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci\nCOPY . .\nCMD [\"npm\", \"run\", \"start\"]\n# Add node_modules, .git and .env to .dockerignore","task":"Explain why copying package files before application source can improve build-cache reuse."},
  {"id":"docker-5","track":"Docker & Containers","level":"Basic","title":"Run containers, ports, logs & environment","duration":"12 min","kind":"flow","summary":"Operate a container and distinguish host ports from container ports.","explain":"Operate a container and distinguish host ports from container ports. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"docker build -t study-api .\ndocker run --rm -p 8080:3000 --name study-api study-api\ndocker logs study-api\ndocker ps","task":"Map a local port to a container port and diagnose a connection refused error."},
  {"id":"docker-6","track":"Docker & Containers","level":"Intermediate","title":"Volumes, networks & Compose","duration":"12 min","kind":"layers","summary":"Run multiple local services with explicit networks and persistent data.","explain":"Run multiple local services with explicit networks and persistent data. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"services:\n  api:\n    build: .\n    ports: [\"8080:3000\"]\n    environment:\n      DATABASE_URL: postgres://app:example@db:5432/study\n    depends_on: [db]\n  db:\n    image: postgres:16\n    volumes: [\"dbdata:/var/lib/postgresql/data\"]\nvolumes:\n  dbdata:","task":"Extend a Compose file with a health check and explain why startup order alone does not prove database readiness."},
  {"id":"docker-7","track":"Docker & Containers","level":"Intermediate","title":"Container security & resource limits","duration":"12 min","kind":"layers","summary":"Run with minimal privileges and bounded resource use.","explain":"Run with minimal privileges and bounded resource use. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"# Example runtime hardening flags\ndocker run --read-only --cap-drop=ALL --memory=256m --cpus=1 study-api\n# Use a non-root user in the image where possible.","task":"Review a container setup for root execution, exposed ports, embedded secrets and unbounded resources."},
  {"id":"docker-8","track":"Docker & Containers","level":"Advanced","title":"Multi-stage builds, scanning & deployment","duration":"12 min","kind":"table","summary":"Ship a smaller runtime image and verify it before release.","explain":"Ship a smaller runtime image and verify it before release. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"FROM node:22-alpine AS build\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci\nCOPY . .\nRUN npm run build\nFROM nginx:alpine\nCOPY --from=build /app/dist /usr/share/nginx/html\n# Scan and pin approved base images in production.","task":"Compare a single-stage and multi-stage image. Add a vulnerability scan and define how to handle a critical finding."},
  {"id":"git-4","track":"Git & GitHub","level":"Basic","title":"Inspect history, diffs & undo safely","duration":"12 min","kind":"flow","summary":"Use history and diff tools to understand changes before rewriting anything.","explain":"Use history and diff tools to understand changes before rewriting anything. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"git status\ngit diff\ngit log --oneline --decorate -10\ngit restore --staged path/to/file\n# Review before using destructive reset commands.","task":"Explain the difference between restoring a file, reverting a commit and resetting a branch."},
  {"id":"git-5","track":"Git & GitHub","level":"Basic","title":"Branching, merge conflicts & collaboration","duration":"12 min","kind":"flow","summary":"Resolve conflicting edits deliberately and verify the resulting file.","explain":"Resolve conflicting edits deliberately and verify the resulting file. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"git fetch origin\ngit switch feature/course-page\ngit merge origin/main\n# Edit conflict markers, run tests, then:\ngit add src/\ngit commit","task":"Walk through a merge conflict and list checks to run before completing the merge."},
  {"id":"git-6","track":"Git & GitHub","level":"Intermediate","title":"Pull requests, reviews & release tags","duration":"12 min","kind":"layers","summary":"Use reviews and tagged versions to make changes traceable.","explain":"Use reviews and tagged versions to make changes traceable. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"git tag -a v1.0.0 -m \"StudyNest 1.0.0\"\ngit show v1.0.0\ngit push origin v1.0.0\n# Use pull-request checks before merging.","task":"Create a pull-request checklist with test evidence, risk, rollback and documentation."},
  {"id":"git-7","track":"Git & GitHub","level":"Intermediate","title":"GitHub Actions, permissions & secrets","duration":"12 min","kind":"layers","summary":"Run automated workflows with narrowly scoped credentials.","explain":"Run automated workflows with narrowly scoped credentials. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"permissions:\n  contents: read\n# Grant write permissions only to the job that requires them.\n# Use OIDC or managed identity where supported.\n# Never echo secrets into logs.","task":"Audit a workflow for unnecessary permissions, unpinned third-party actions and secret exposure."},
  {"id":"git-8","track":"Git & GitHub","level":"Advanced","title":"Protected branches, supply chain & recovery","duration":"12 min","kind":"table","summary":"Protect important branches and plan recovery from a bad release or leaked credential.","explain":"Protect important branches and plan recovery from a bad release or leaked credential. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"# Repository controls to configure\n# - Required review and status checks\n# - Restricted direct pushes\n# - Dependency and secret scanning\n# - Signed/reviewed releases where appropriate\n# - Tested restore and credential-rotation procedures","task":"Design a secure repository policy for a small team and explain how to recover from an accidentally committed secret."},
  {"id":"k8s-4","track":"Kubernetes","level":"Basic","title":"Labels, selectors & service discovery","duration":"12 min","kind":"flow","summary":"Connect workloads using stable labels and selectors rather than changing pod IPs.","explain":"Connect workloads using stable labels and selectors rather than changing pod IPs. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"apiVersion: v1\nkind: Service\nmetadata:\n  name: study-api\nspec:\n  selector:\n    app: study-api\n  ports:\n    - port: 80\n      targetPort: 8080","task":"Explain how a Service selector finds pods and diagnose a selector-label mismatch."},
  {"id":"k8s-5","track":"Kubernetes","level":"Basic","title":"Namespaces, kubectl & configuration","duration":"12 min","kind":"flow","summary":"Use namespaces and declarative manifests to keep workloads organized.","explain":"Use namespaces and declarative manifests to keep workloads organized. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"kubectl get pods -n development\nkubectl describe deployment study-api -n development\nkubectl logs deployment/study-api -n development\nkubectl apply -f deployment.yaml","task":"Create a safe troubleshooting sequence using get, describe, logs and events before changing a deployment."},
  {"id":"k8s-6","track":"Kubernetes","level":"Intermediate","title":"ConfigMaps, Secrets & health probes","duration":"12 min","kind":"layers","summary":"Separate configuration from images and use probes for the right health signals.","explain":"Separate configuration from images and use probes for the right health signals. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"readinessProbe:\n  httpGet:\n    path: /health/ready\n    port: 8080\n  initialDelaySeconds: 5\n  periodSeconds: 10\nlivenessProbe:\n  httpGet:\n    path: /health/live\n    port: 8080\n  periodSeconds: 20","task":"Explain readiness versus liveness. Describe why Kubernetes Secret objects still require access controls and encryption configuration."},
  {"id":"k8s-7","track":"Kubernetes","level":"Intermediate","title":"Resources, autoscaling & rollout management","duration":"12 min","kind":"layers","summary":"Set realistic resource requests/limits and watch rollout health.","explain":"Set realistic resource requests/limits and watch rollout health. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"resources:\n  requests:\n    cpu: \"100m\"\n    memory: \"128Mi\"\n  limits:\n    cpu: \"500m\"\n    memory: \"512Mi\"\n# kubectl rollout status deployment/study-api","task":"Choose resource values from observed metrics and describe what to inspect when a pod enters CrashLoopBackOff."},
  {"id":"k8s-8","track":"Kubernetes","level":"Advanced","title":"Network policies, RBAC & production reliability","duration":"12 min","kind":"table","summary":"Restrict service communication and grant narrowly scoped cluster permissions.","explain":"Restrict service communication and grant narrowly scoped cluster permissions. Start with the smallest working example, observe its behavior, then change one thing at a time. In real projects, make assumptions explicit, validate external input, and prefer readable code over clever shortcuts. Test both normal behavior and edge cases before relying on it.","code":"apiVersion: rbac.authorization.k8s.io/v1\nkind: Role\nmetadata:\n  name: pod-reader\nrules:\n  - apiGroups: [\"\"]\n    resources: [\"pods\"]\n    verbs: [\"get\", \"list\", \"watch\"]\n# Bind this Role only to the required service account.","task":"Design a production readiness checklist covering RBAC, network policies, disruption budgets, backups, upgrades and rollback."}
]

const trackIntros = {
  'Python': { what:'A general-purpose language used to build scripts, APIs, automation and data applications.', why:'Readable syntax and a large ecosystem help teams deliver features quickly and automate repetitive work.', where:'Backend services, Django/FastAPI APIs, data engineering, testing, scripting and AI/ML workflows.', path:'Syntax and collections → functions and modules → OOP, files and testing → generators, async, profiling and architecture.' },
  'SQL': { what:'A language for querying and changing data stored in relational databases.', why:'It lets applications retrieve accurate information, combine related tables and summarize business data.', where:'Reporting, application backends, analytics, data quality checks and database operations.', path:'SELECT and filters → joins and aggregates → subqueries/window functions → indexes, transactions and query plans.' },
  'REST APIs': { what:'A common way for software systems to exchange resources over HTTP.', why:'APIs let web, mobile and backend services communicate through a stable contract.', where:'Frontend-to-backend calls, integrations, microservices, mobile apps and partner systems.', path:'HTTP and JSON → methods/status codes → validation and pagination → auth, rate limits, idempotency and reliability.' },
  'Java': { what:'A statically typed, object-oriented language that commonly runs on the Java Virtual Machine (JVM).', why:'It offers strong tooling, portability and mature libraries for large, long-lived applications.', where:'Enterprise backends, Spring services, Android legacy/current projects, financial systems and distributed services.', path:'Types and control flow → classes and collections → generics, streams, exceptions, concurrency and JVM performance.' },
  'JavaScript': { what:'The programming language of the web; it also runs on servers and tooling through runtimes such as Node.js.', why:'It makes pages interactive and enables teams to share language skills across browser and server code.', where:'Frontend interfaces, Node.js APIs, browser automation, serverless functions and full-stack applications.', path:'Variables and functions → arrays/objects and DOM → promises and modules → closures, performance and architecture.' },
  'C Programming': { what:'A compiled, procedural language that gives developers close control over memory and system resources.', why:'It is useful when performance, small runtimes or low-level hardware access matters.', where:'Operating systems, embedded devices, drivers, networking libraries and performance-sensitive components.', path:'Types and control flow → arrays and pointers → structs and functions → dynamic memory, debugging and undefined behavior.' },
  'HTML & CSS': { what:'HTML gives web content structure; CSS controls its visual presentation and layout.', why:'Together they are the foundation of accessible, responsive web pages.', where:'Websites, dashboards, forms, design systems, email templates and app interfaces.', path:'Semantic markup → selectors and box model → Flexbox/Grid and responsive layouts → accessibility and maintainable design systems.' },
  'DevOps': { what:'A set of practices that connects software development and operations through collaboration, automation and feedback.', why:'It makes software delivery repeatable, observable and safer to change.', where:'CI/CD pipelines, automated testing, release engineering, monitoring and incident response.', path:'Git and CI/CD basics → build/deploy pipelines and IaC → monitoring and release patterns → SLOs, resilience and incident learning.' },
  'Cloud Fundamentals': { what:'Cloud platforms provide compute, storage, networking, identity and managed services over the internet.', why:'Teams can provision resources on demand and choose how much infrastructure they operate themselves.', where:'Hosting web apps/APIs, data platforms, backups, analytics, identity and scalable production systems.', path:'Service models and regions → networking and IAM → deployment and observability → resilience, recovery and cost management.' },
  'Linux & Shell': { what:'Linux is an operating system used widely on servers; shells let you control it with commands and scripts.', why:'Command-line skills make server administration, automation and troubleshooting faster and repeatable.', where:'Cloud VMs, containers, CI runners, web servers, log analysis and deployment scripts.', path:'Filesystem and commands → permissions and pipes → shell scripts and processes → services, logs and troubleshooting.' },
  'Docker & Containers': { what:'Docker packages an application and its dependencies into an image that can run as a container.', why:'Containers make environments more consistent between development, testing and deployment.', where:'Local development, CI builds, microservices, test environments and cloud deployments.', path:'Images and containers → Dockerfiles and Compose → networking and volumes → multi-stage builds, scanning and runtime security.' },
  'Git & GitHub': { what:'Git tracks source-code history; GitHub hosts repositories and adds collaboration and automation features.', why:'Teams can review changes, work in parallel, trace releases and automate quality checks.', where:'Feature development, pull requests, code reviews, release tagging, issue tracking and GitHub Actions.', path:'Commits and branches → pull requests and conflict resolution → tags and releases → protected branches and secure CI/CD.' },
  'Kubernetes': { what:'Kubernetes orchestrates containerized workloads across a cluster of machines.', why:'It can automate scheduling, service discovery, scaling and recovery for complex container deployments.', where:'Platforms running many services, managed cloud clusters and workloads that need orchestration at scale.', path:'Pods, Deployments and Services → configuration and probes → resource management and autoscaling → rollout safety and cluster operations.' },
  'Generative AI': { what:'Generative AI uses trained models to create or transform text, code, images, audio and other content from instructions and context.', why:'It can help explain concepts, summarize trusted information, draft content, support coding and build natural-language interfaces—but outputs must be evaluated.', where:'Learning assistants, document search, support tools, content drafting, coding helpers and multimodal applications.', path:'Model and prompt fundamentals → API integration and embeddings → RAG and structured output → evaluation, safety, cost and production architecture.' },
  'Agentic AI': { what:'Agentic AI systems use a model to plan steps, choose approved tools, observe results and work toward a goal within defined boundaries.', why:'Agents can handle multi-step tasks when a fixed script is too rigid, but need limits, validation, permissions and human oversight.', where:'Research assistants, learning-plan builders, workflow automation, knowledge operations and tool-using support systems.', path:'Agent concepts and tool contracts → bounded loops and planning → memory, RAG and coordination → approvals, recovery, evaluation and secure deployment.' },

}

const trackTeachingGuides = {
  'Python': { analogy:'Think of Python as a set of clear instructions for a helpful assistant. Variables hold facts, conditions make decisions, loops repeat work, and functions package steps you want to reuse.', realWorld:'A backend service might receive a request, validate the input, query a database, and return JSON. Python helps express each step clearly.', pitfalls:'Watch indentation, mutable default arguments, broad exception handling, and accidentally modifying a shared list or dictionary.', terms:'Variable · Type · Condition · Loop · Function · Collection · Exception' },
  'SQL': { analogy:'Imagine a spreadsheet with named columns and many rows. SQL lets you ask precise questions about those rows and combine information from related sheets.', realWorld:'A reporting query may filter orders by date, join customers, group orders by customer, and calculate totals.', pitfalls:'Check JOIN conditions to avoid duplicate rows, use IS NULL for missing values, and verify UPDATE/DELETE filters before changing data.', terms:'Table · Row · Column · Primary key · JOIN · Aggregate · Index · Transaction' },
  'REST APIs': { analogy:'Think of an API as a service counter. A request clearly says what resource you want and what action you intend; the response tells you the result and returns data or an error.', realWorld:'A mobile app can call GET /api/courses to display courses, or POST /api/courses to ask the server to create one.', pitfalls:'Validate client input, use appropriate status codes, check permissions on the server, set timeouts, and never expose passwords or tokens in logs.', terms:'Request · Response · Endpoint · HTTP method · Status code · JSON · Authentication · Authorization' },
  'Java': { analogy:'Java is like a blueprint-driven workshop: types describe the shape of data, classes define objects, and the JVM runs compiled bytecode on supported platforms.', realWorld:'Java is common in long-running enterprise services where clear types, mature libraries and structured code help large teams.', pitfalls:'Distinguish primitive values from object references, handle exceptions intentionally, and use equals() rather than == for most object-value comparisons.', terms:'Type · Class · Object · Method · Interface · Exception · JVM' },
  'JavaScript': { analogy:'JavaScript gives a webpage behavior. Events trigger functions, arrays hold lists, and promises represent work that may finish later.', realWorld:'A browser can fetch API data, show a loading state, render results, and display a useful error if the request fails.', pitfalls:'Understand undefined versus null, avoid assuming asynchronous work finishes immediately, and handle rejected promises.', terms:'Variable · Function · Array · Object · Promise · async/await · Module' },
  'C Programming': { analogy:'C lets you work close to the machine. A variable stores a value, while a pointer stores the address where another value lives.', realWorld:'C is used in embedded systems, operating-system components and libraries where resource use and low-level control matter.', pitfalls:'Never dereference an invalid pointer, read uninitialized memory, write past array bounds, or use freed memory.', terms:'Type · Array · Pointer · Address · Struct · Allocation · Undefined behavior' },
  'HTML & CSS': { analogy:'HTML is the structure of a room; CSS is the layout, colors and spacing that make it comfortable to use.', realWorld:'Semantic HTML gives forms, headings and navigation meaning. CSS makes them readable on mobile, tablet and desktop screens.', pitfalls:'Do not use elements only for their appearance; keep heading order logical, preserve keyboard focus, and test layouts at narrow widths.', terms:'Element · Attribute · Semantic HTML · Selector · Box model · Flexbox · Grid · Responsive design' },
  'DevOps': { analogy:'DevOps is a repeatable delivery assembly line: source changes are checked, built, tested, deployed and monitored rather than handled by fragile manual steps.', realWorld:'A CI/CD workflow can run tests on a pull request and publish a verified application after an approved merge.', pitfalls:'Do not store secrets in source code, skip health checks, or deploy without a rollback and monitoring plan.', terms:'Version control · CI · CD · Artifact · Infrastructure as code · Monitoring · Rollback' },
  'Cloud Fundamentals': { analogy:'Cloud computing is like renting managed building blocks: compute runs code, storage keeps data, networking connects services, and identity controls access.', realWorld:'A web app may run on a managed app platform, store files in object storage, and use managed identity to access another service.', pitfalls:'Apply least privilege, understand public network exposure, set budgets/alerts, and plan backups and recovery before production.', terms:'Compute · Storage · Region · Availability zone · IAM · Network · Scalability · Cost' },
  'Linux & Shell': { analogy:'Linux is the workshop operating system; shell commands are short instructions. Pipes pass one command’s output to the next.', realWorld:'Engineers use commands to inspect files, check processes, search logs, automate deployments and diagnose server issues.', pitfalls:'Check the current directory before destructive commands, quote paths with spaces, and avoid running privileged commands without understanding them.', terms:'Path · Process · Permission · Pipe · Environment variable · Service · Log' },
  'Docker & Containers': { analogy:'An image is a recipe/package template; a container is a running instance made from that image. Volumes keep selected data outside the container lifecycle.', realWorld:'A team can build one application image and run it in development, automated tests and a cloud environment with consistent dependencies.', pitfalls:'Do not bake secrets into images, run as root unnecessarily, or assume files written only inside a container survive replacement.', terms:'Image · Container · Dockerfile · Registry · Port · Volume · Compose' },
  'Git & GitHub': { analogy:'Git is a time machine for a project. Commits are saved checkpoints, branches are parallel lines of work, and pull requests are a place to review changes before merging.', realWorld:'A feature branch can be tested by CI, reviewed by teammates, and merged into the release branch after checks pass.', pitfalls:'Inspect staged changes before committing, pull before resolving conflicts, and never commit credentials or generated secrets.', terms:'Repository · Commit · Branch · Merge · Conflict · Pull request · Tag · Workflow' },
  'Kubernetes': { analogy:'Kubernetes is a coordinator for containers. You describe the desired state, and controllers keep working to move the running system toward that state.', realWorld:'A Deployment can maintain multiple application replicas, a Service gives them a stable network address, and probes help Kubernetes detect unhealthy containers.', pitfalls:'Set realistic resource requests/limits, configure readiness separately from liveness, and avoid putting sensitive values in plain ConfigMaps.', terms:'Cluster · Node · Pod · Deployment · Service · Probe · Resource request · Rollout' },
  'Generative AI': { analogy:'Think of a generative model as a writing partner that predicts a useful continuation from the instructions and context you give it. It can be fluent and still be wrong, so evidence and checks matter.', realWorld:'A study assistant can explain a concept, retrieve approved course notes, draft a quiz and return structured results that the application validates.', pitfalls:'Do not trust every generated claim, expose API keys in frontend code, send sensitive data without approval, or confuse a plausible answer with a sourced answer.', terms:'LLM · Token · Prompt · Embedding · Vector search · RAG · Structured output · Evaluation · Hallucination' },
  'Agentic AI': { analogy:'An agent is like a careful assistant with a checklist and a small set of tools: it decides the next step, checks what happened, and stops when the task is done or it needs permission.', realWorld:'A learning agent might search public lessons, group them by difficulty and draft a schedule while asking before changing a learner account or sending a message.', pitfalls:'Limit loops and budgets, validate every tool call, keep permissions in the application, treat retrieved text as untrusted, and require approval for consequential actions.', terms:'Agent loop · Tool calling · State · Planning · Memory · Handoff · Idempotency · Human approval · Trace' },

}

function explainCodeLine(line, track) {
  const value = line.trim()
  if (!value) return 'This blank line separates logical steps and improves readability.'
  if (/^(#|--|\/\/|\/\*)/.test(value)) return 'This is a comment for the reader; it documents intent and is not executed as normal program logic.'
  if (/^(import |from )/.test(value)) return 'This brings in functionality defined elsewhere so the example can reuse it.'
  if (/^(def |async def |function )/.test(value)) return 'This starts a reusable function. The indented body describes the work performed when it is called.'
  if (/^class /.test(value)) return 'This defines a class: a reusable description of the data and behavior its objects will have.'
  if (/^(if |elif |else:|WHEN |CASE )/.test(value)) return 'This introduces a decision branch. The condition determines which path is selected.'
  if (/^(for |while )/.test(value)) return 'This begins a loop, repeating the indented work for items or while a condition remains true.'
  if (/^(return |yield )/.test(value)) return value.startsWith('yield') ? 'This yields one value to the caller while preserving the generator so it can continue later.' : 'This sends a result back to the caller and ends the current function call.'
  if (/^(SELECT|WITH )/i.test(value)) return 'This starts a query or named query stage to describe which data should be returned.'
  if (/^(FROM|JOIN|LEFT JOIN|INNER JOIN)/i.test(value)) return 'This identifies the source table or connects related records using a relationship.'
  if (/^WHERE /i.test(value)) return 'This filters individual rows. Only rows matching the condition continue through the query.'
  if (/^(GROUP BY|HAVING|ORDER BY|LIMIT)/i.test(value)) return 'This shapes the result: grouping summarizes rows, HAVING filters groups, ORDER BY sorts, and LIMIT caps returned rows.'
  if (/^(CREATE|INSERT|UPDATE|DELETE|ALTER|BEGIN|COMMIT|ROLLBACK)/i.test(value)) return 'This is a database command that defines data structures, changes records, or controls a transaction. Check its scope before running it on real data.'
  if (/^(GET|POST|PUT|PATCH|DELETE)\s/.test(value)) return 'This describes an HTTP request: the method communicates the intended action and the path identifies the resource.'
  if (/^(print\(|console\.log\(|System\.out|printf\()/.test(value)) return 'This prints a value so you can inspect the program’s result while learning or debugging.'
  if (/^\}/.test(value) || /^\];?$/.test(value)) return 'This closes a block or collection opened earlier; check matching brackets when debugging syntax.'
  if (/^[\w$]+.*=/.test(value)) return 'This assigns a value to a name or property. Read the expression on the right first, then note where the result is stored.'
  if (/^\s*[-\w]+\s+/.test(value) && /\s→\s/.test(value)) return 'This shows an operation and its expected response or result.'
  return 'Read this line as one step in the example. Identify its input, the operation it performs, and what later line uses its result.'
}

const levelOrder = { Basic: 0, Intermediate: 1, Advanced: 2 }
const lessons = baseLessons.map((lesson, index) => ({ ...lesson, _order: index })).sort((a, b) => tracksSortOrder(a.track, b.track) || levelOrder[a.level] - levelOrder[b.level] || a._order - b._order).map(({ _order, ...lesson }) => lesson)
function tracksSortOrder(a, b) { return a.localeCompare(b) }
const levels = ['All levels', 'Basic', 'Intermediate', 'Advanced']
const tracks = ['All topics', ...new Set(lessons.map((lesson) => lesson.track))]

